// ─── v192: AUCTION DEBT — shared budget-credit helper ────────────────────────
// Call this instead of `team.budget += amount` for any income payment.
// Returns { newBudget, debtRepaid, debtCleared } so callers can display toasts.
// Does NOT modify the team object — callers must apply returned newBudget.
// The highestAuctionDebt / seasonHighestDebt / totalDebtRepaid fields on the
// team object are updated in-place (safe: callers already hold a draft copy).
function applyIncomeWithDebtRepayment(team, amount) {
  const prevBudget = team.budget;
  const wasInDebt  = prevBudget < 0;
  let debtRepaid   = 0;
  let debtCleared  = false;

  if (wasInDebt) {
    const debtBefore = Math.abs(prevBudget); // positive magnitude
    debtRepaid = Math.min(debtBefore, amount);
    debtCleared = amount >= debtBefore;      // income exceeds outstanding debt
    // Track how much debt was repaid this career
    team.totalDebtRepaid = Math.round(((team.totalDebtRepaid || 0) + debtRepaid) * 10) / 10;
  }

  const newBudget = Math.round((prevBudget + amount) * 10) / 10;

  // Update peak-debt watermarks (only while the budget is/was negative)
  if (prevBudget < 0) {
    const debtMag = Math.abs(prevBudget);
    team.highestAuctionDebt  = Math.round(Math.max(team.highestAuctionDebt  || 0, debtMag) * 10) / 10;
    team.seasonHighestDebt   = Math.round(Math.max(team.seasonHighestDebt   || 0, debtMag) * 10) / 10;
  }

  team.budget = newBudget;
  return { newBudget, debtRepaid, debtCleared, wasInDebt };
}

// ─── v183: PERSISTENT DRIVER FORM SYSTEM ────────────────────────────────────
// FORM_VALUES / FORM_LABELS / FORM_COLORS above are UNCHANGED — gameplay
// balance (the ±3/±2/0 modifiers) is untouched. Everything below only changes
// HOW OFTEN and HOW a driver's form is allowed to move, replacing the old
// "fresh random roll every single race" behaviour with a momentum-driven,
// duration-gated system so form persists believably across multiple races.

// Typical number of races a driver stays at a given form before becoming
// eligible to move again. This is a minimum hold time, not a guarantee of
// change — see advanceDriverForm() below.
const FORM_DURATION_RANGE = { Excellent:[2,4], Good:[2,3], Normal:[2,4], Poor:[2,3], Terrible:[2,4] };

// Tuning knobs for the momentum/eligibility roll — kept as named constants so
// the feel of the system can be adjusted in one place without touching logic.
const FORM_REVERSION_TO_NORMAL  = 0.5;   // gentle pull back toward Normal with no strong momentum
const FORM_MOVE_CHANCE_SCALE    = 0.16;  // converts momentum score → probability of moving
const FORM_MOVE_CHANCE_MIN      = 0.18;
const FORM_MOVE_CHANCE_MAX      = 0.70;  // never guaranteed, even under huge momentum
const FORM_RARE_JUMP_THRESHOLD  = 7;     // |momentum| needed before a 2-step jump is even possible
const FORM_RARE_JUMP_CHANCE     = 0.05;  // and even then, only 5% of the time
const FORM_MOMENTUM_DECAY       = 0.4;   // momentum kept (vs reset) after a transition
const FORM_MOMENTUM_CLAMP       = 9;

// Small per-tier nudges only — better drivers are slightly more resistant to
// sliding into bad form and recover from it a little faster. Average drivers
// (Strong tier) are the 1.0 baseline; the spread is deliberately narrow so
// this never overpowers the rating-driven race simulation.
const FORM_TIER_STABILITY = {
  GOAT:    { decline:0.8,  improve:1.2,  badFormRecovery:0.75 },
  Elite:   { decline:0.9,  improve:1.1,  badFormRecovery:0.85 },
  Strong:  { decline:1.0,  improve:1.0,  badFormRecovery:1.0  },
  Average: { decline:1.1,  improve:0.95, badFormRecovery:1.1  },
  Weak:    { decline:1.2,  improve:0.9,  badFormRecovery:1.2  },
};
function formStabilityFor(tier) { return FORM_TIER_STABILITY[tier] || FORM_TIER_STABILITY.Strong; }

// Position on the form scale: 0 = Excellent (best) .. 4 = Terrible (worst).
// Used to enforce "only one step at a time" (Excellent→Terrible in one race
// is never possible — it would require crossing this whole scale at once).
function formScaleIndex(form) {
  const i = FORM_LABELS.indexOf(form);
  return i === -1 ? 2 : i; // unknown/legacy value → treat as Normal
}

// Draws a fresh "races remaining at this form" timer. Poor/Terrible timers
// are additionally scaled by the driver's tier recovery speed (GOAT/Elite
// drivers spend less time stuck in a slump).
function rollFormDuration(form, tier) {
  const [lo, hi] = FORM_DURATION_RANGE[form] || [2,3];
  let races = lo + Math.floor(Math.random() * (hi - lo + 1));
  if (form === "Poor" || form === "Terrible") {
    races = Math.max(1, Math.round(races * formStabilityFor(tier).badFormRecovery));
  }
  return races;
}

// Idempotent migration: gives any driver object (old saves, freshly generated
// pool drivers, rookies) the fields the persistent form system needs, without
// touching anything else already on the driver (rating/tier/traits/stats are
// left exactly as they were). Safe to call repeatedly.
function ensureDriverFormState(driver) {
  if (driver && typeof driver.formRaceTimer === "number" && driver.form) return driver;
  const form = driver?.form || "Normal";
  return {
    ...driver,
    form,
    formRaceTimer: rollFormDuration(form, driver?.tier),
    formMomentum: 0,
    formGoodStreak: 0,
    formBadStreak: 0,
  };
}

// Buckets a single race result into a performance category used to nudge
// momentum. A retirement (or any non-finish) always counts as the worst
// bucket regardless of the numeric position it was assigned.
function categorizeFormResult(result) {
  if (!result || result.retired) return "outside";
  const pos = result.position;
  if (pos === 1) return "win";
  if (pos <= 3) return "podium";
  if (pos <= 5) return "top5";
  if (pos <= 10) return "points";
  return "outside";
}
// Base momentum nudge per category. Deliberately small — it should take
// several races of consistent results to swing a driver's form, not one race.
const FORM_MOMENTUM_DELTA = { win:3, podium:2, top5:1, points:0, outside:-2 };

// Advances a single driver's persistent form by exactly one race and returns
// a NEW driver object (never mutates the input). `result` is that driver's
// race result this race, or null/undefined if they didn't race at all (e.g.
// benched) — in that case only the hold timer ticks down, no performance
// influence is applied.
function advanceDriverForm(driver, result) {
  const d = ensureDriverFormState(driver);
  if (!result) return { ...d, formRaceTimer: Math.max(0, d.formRaceTimer - 1) };

  const stability = formStabilityFor(d.tier);
  const category = categorizeFormResult(result);

  // ── Update momentum & streaks from this race's result ────────────────────
  let momentum = d.formMomentum + (FORM_MOMENTUM_DELTA[category] ?? 0);
  let goodStreak = (category === "win" || category === "podium") ? d.formGoodStreak + 1 : 0;
  let badStreak  = (category === "outside") ? d.formBadStreak + 1 : 0;
  if (goodStreak >= 2) momentum += 1; // multiple podiums/wins in succession → extra push to improve
  if (badStreak  >= 2) momentum -= 1; // back-to-back poor finishes → extra slide toward decline
  momentum = Math.max(-FORM_MOMENTUM_CLAMP, Math.min(FORM_MOMENTUM_CLAMP, momentum));

  let timer = d.formRaceTimer - 1;
  let form = d.form;

  // Form only becomes eligible to move once its current "typical duration"
  // timer has run out — this is what makes form persist across races instead
  // of changing every result.
  if (timer <= 0) {
    const idx = formScaleIndex(form);
    // Gentle pull back toward Normal over time even with no strong momentum,
    // so one lucky/unlucky race doesn't lock a driver into an extreme form
    // forever — blended with the momentum-driven scores below.
    const improveScore = (idx > 2 ? FORM_REVERSION_TO_NORMAL : 0) + Math.max(0, momentum) * stability.improve;
    const declineScore = (idx < 2 ? FORM_REVERSION_TO_NORMAL : 0) + Math.max(0, -momentum) * stability.decline;
    const total = improveScore + declineScore;

    if (total > 0) {
      // Never guaranteed — even a strongly-favoured direction only has a
      // capped chance of actually producing a change on any given check.
      const moveChance = Math.max(FORM_MOVE_CHANCE_MIN, Math.min(FORM_MOVE_CHANCE_MAX, total * FORM_MOVE_CHANCE_SCALE));
      if (Math.random() < moveChance) {
        const improving = Math.random() < (improveScore / total);
        const direction = improving ? -1 : 1;
        // Extremely rare 2-step jump, only under sustained, lopsided
        // momentum — still can never cross from Excellent all the way to
        // Terrible (or back) since the maximum step is 2, not 4.
        let steps = 1;
        if (Math.abs(momentum) >= FORM_RARE_JUMP_THRESHOLD && Math.random() < FORM_RARE_JUMP_CHANCE) steps = 2;
        const newIdx = Math.max(0, Math.min(FORM_LABELS.length - 1, idx + direction * steps));
        form = FORM_LABELS[newIdx];
      }
    }

    if (form !== d.form) {
      timer = rollFormDuration(form, d.tier);
      momentum = Math.round(momentum * FORM_MOMENTUM_DECAY); // fresh evidence needed for the next move
      goodStreak = Math.floor(goodStreak / 2);
      badStreak = Math.floor(badStreak / 2);
    } else {
      timer = 1; // re-check again after the next race rather than waiting a full new duration
    }
  }

  return { ...d, form, formRaceTimer: timer, formMomentum: momentum, formGoodStreak: goodStreak, formBadStreak: badStreak };
}
