// ─── SINGLE SOURCE OF TRUTH FOR GOAT / DYNASTY SCORING ──────────────────────
// ALL scoring formulas in the game — Hall of Fame rankings, dynasty tier
// calculations, end-game standings, unlock checks, and displayed formula text —
// MUST derive from these weights. Never hardcode multipliers elsewhere.
// v96: Unified. Previous code had two divergent sets of weights:
//   • computeDynastyScore / checkUnlocks used ×1000 / ×50 / ×15 (old constants)
//   • HallOfFameScreen / EndGameScreen used ×300 / ×40 / ×10 (v90 rebalance)
// Canonical weights are now the v90 rebalanced values (×300 / ×40 / ×10).
// GOAT Score = (Champs × 300) + (Wins × 40) + (Podiums × 10) + Career Points
// Max possible 4-season score: 4×300 + (64wins×40) + (192pods×10) + ~6000pts ≈ 10,120+
const GOAT_SCORING = {
  championship: 300,
  win:          40,
  podium:       10,
  point:        1,
};

// Kept as deprecated aliases so any third-party save-file tooling still compiles;
// nothing inside this file should reference these — use GOAT_SCORING instead.
/** @deprecated Use GOAT_SCORING.championship */
const DYNASTY_CHAMPIONSHIP_SCORE = GOAT_SCORING.championship;
/** @deprecated Use GOAT_SCORING.win */
const DYNASTY_WIN_SCORE          = GOAT_SCORING.win;
/** @deprecated Use GOAT_SCORING.podium */
const DYNASTY_PODIUM_SCORE       = GOAT_SCORING.podium;

/**
 * calculateGoatScore — canonical GOAT/dynasty scoring helper.
 * Accepts any object with optional: championships, wins, podiums, points.
 * Used by: computeDynastyScore, HallOfFameScreen (driver + team lists),
 *          EndGameScreen overallStandings sort, checkUnlockConditions.
 */
function calculateGoatScore(stats) {
  return (
    (stats.championships || 0) * GOAT_SCORING.championship +
    (stats.wins          || 0) * GOAT_SCORING.win          +
    (stats.podiums       || 0) * GOAT_SCORING.podium       +
    (stats.points        || 0) * GOAT_SCORING.point
  );
}

// ─── CAREER FINALE: MANAGER RANK ────────────────────────────────────────────
// Labels a finished 4-season career using the SAME calculateGoatScore() output
// already used everywhere else (HallOfFameScreen, EndGameScreen, dynasty tiers).
// This is purely a presentational bucketing on top of the existing score — it
// introduces no new scoring math and never recalculates GOAT/Dynasty values.
const MANAGER_RANKS = [
  { label:"NEWCOMER MANAGER",     minScore:0,    color:"#a78bfa", glow:"rgba(167,139,250,0.35)" },
  { label:"COMPETITIVE MANAGER", minScore:1200, color:"#4fc3f7", glow:"rgba(79,195,247,0.35)" },
  { label:"CHAMPION MANAGER",    minScore:2800, color:"#00d25b", glow:"rgba(0,210,91,0.4)" },
  { label:"ELITE MANAGER",       minScore:4800, color:"#fb8c00", glow:"rgba(251,140,0,0.4)" },
  { label:"LEGENDARY MANAGER",   minScore:7200, color:"#f4d03f", glow:"rgba(244,208,63,0.45)" },
  { label:"LEGACY MANAGER",      minScore:9500, color:"#e10600", glow:"rgba(225,6,0,0.5)" },
];
function getManagerRank(score) {
  let rank = MANAGER_RANKS[0];
  for (const r of MANAGER_RANKS) { if (score >= r.minScore) rank = r; }
  return rank;
}

// Development-mode consistency guard: warn if someone re-introduces a second
// scoring constant with a different value. Uses typeof to stay browser-safe
// (process.env is not available outside Node/bundler environments).
if (typeof __DEV__ !== "undefined" ? __DEV__ : (typeof location !== "undefined" && location.hostname === "localhost")) {
  if (
    DYNASTY_CHAMPIONSHIP_SCORE !== GOAT_SCORING.championship ||
    DYNASTY_WIN_SCORE          !== GOAT_SCORING.win          ||
    DYNASTY_PODIUM_SCORE       !== GOAT_SCORING.podium
  ) {
    console.warn(
      "[GOAT SCORING] Inconsistency detected: DYNASTY_*_SCORE constants no longer match " +
      "GOAT_SCORING. All formulas should use calculateGoatScore(). " +
      "Check DYNASTY_CHAMPIONSHIP_SCORE, DYNASTY_WIN_SCORE, DYNASTY_PODIUM_SCORE."
    );
  }
}
