// ============================================================
// ACHIEVEMENT STATE INITIALIZER
// ============================================================
const initAchievements = () => {
  const unlocked = {};
  const progress = {};
  ACHIEVEMENT_DEFS.forEach((a) => {
    unlocked[a.id] = false;
    progress[a.id] = 0;
  });
  return { unlocked, progress, unlockDates: {}, unlockSeasons: {} };
};

// ============================================================
// ACHIEVEMENT STATS DERIVER
// Reads gameState and derives current stat values.
// ============================================================
const deriveStats = (gameState) => {
  if (!gameState) return {};

  // v21 gameState shape: { teams, allRaceResults, seasonChampions, currentSeason, ... }
  const player = (gameState.teams || []).find(t => !t.isAI);
  if (!player) return {};

  const allRaceResults = gameState.allRaceResults || [];
  const seasonChampions = gameState.seasonChampions || [];

  // Wins & podiums from allRaceResults for the player's drivers
  const playerDriverIds = new Set((player.drivers || []).map(d => d.id));
  let totalWins = player.raceWins || 0;
  let totalPodiums = player.podiums || 0;
  // careerPoints = totalPoints is the cumulative career points field (NEVER season-only)
  let careerPoints = player.totalPoints || 0;

  // Win streak: longest EVER win streak (so hat_trick/on_fire achievements don't reset)
  let winStreak = 0;
  let longestWinStreakEver = 0;
  let currentRun = 0;
  for (let i = 0; i < allRaceResults.length; i++) {
    const r = allRaceResults[i];
    const winner = (r.results || [])[0];
    if (winner && winner.teamId === player.id) {
      currentRun++;
      longestWinStreakEver = Math.max(longestWinStreakEver, currentRun);
    } else {
      currentRun = 0;
    }
  }
  // Current streak from the end (for display)
  winStreak = longestWinStreakEver; // Use longest ever so hat_trick/hot_streak achievements persist

  // Championships: seasonChampions where player was champion
  const playerChamps = seasonChampions.filter(s => s.champion && s.champion.id === player.id);
  const totalChampionships = playerChamps.length;

  // Consecutive championships
  const champSeasons = playerChamps.map(s => s.season).sort((a,b) => a-b);
  let maxStreak = champSeasons.length > 0 ? 1 : 0;
  let streak = 1;
  for (let i = 1; i < champSeasons.length; i++) {
    if (champSeasons[i] === champSeasons[i-1] + 1) { streak++; maxStreak = Math.max(maxStreak, streak); }
    else streak = 1;
  }
  const consecutiveChampionships = maxStreak;

  // Seasons completed — use player team's seasonsCompleted field if available, otherwise derive
  const seasonsCompleted = player.seasonsCompleted || (gameState.currentSeason > 1 ? gameState.currentSeason - 1 : 0);

  // HOF inductions: count seasons where a driver was inducted (any season completed = HOF entry)
  // We use seasons logged in HOF as proxy for inductees
  let hofInductions = 0;
  try {
    const hofRaw = localStorage.getItem("f1_hall_of_fame_v1");
    if (hofRaw) {
      const hof = JSON.parse(hofRaw);
      // Count any completed seasons in HOF — each season inducts at least one driver
      hofInductions = (hof.seasons || []).length;
    }
  } catch(_) {}

  // Perfect season: all races in a season won by player
  // Perfect season: check each completed season if player won all races
  let perfectSeasons = player.perfectSeasons || 0;
  // We check allRaceResults grouped by season
  const seasonRaceMap = {};
  allRaceResults.forEach(r => {
    const sNum = r.race?.season || 1;
    if (!seasonRaceMap[sNum]) seasonRaceMap[sNum] = [];
    seasonRaceMap[sNum].push(r);
  });
  perfectSeasons = Object.values(seasonRaceMap).filter(races => {
    const normalRaces = races;
    if (normalRaces.length < RACES_PER_SEASON) return false; // incomplete season — don't count
    return normalRaces.every(r => {
      const winner = (r.results || [])[0];
      return winner && winner.teamId === player.id;
    });
  }).length;

  // teamValue: compute as cumulative earnings + wins + championships bonus (in M, then * 1M for comparison)
  // Base: totalEarnings (in M) + wins*2M + champs*50M
  const teamValueM = (player.totalEarnings || 0) + (player.raceWins || 0) * 2 + totalChampionships * 50;
  const teamValue = teamValueM * 1_000_000;
  const totalEarnings = (player.totalEarnings || 0) * 1_000_000;

  // GOAT driver detection: check if any player driver has 95+ rating, or is all-time leader in wins/championships
  let goatUnlocked = 0;
  const playerDrivers = (player.drivers || []);
  // Check dynasty score / tier (GOAT tier threshold matches DYNASTY_TIERS "GOAT" entry)
  try {
    const hofRaw2 = localStorage.getItem("f1_hall_of_fame_v1");
    const hofForGoat = hofRaw2 ? JSON.parse(hofRaw2) : null;
    const dynastyScore = hofForGoat ? calculateGoatScore({
      championships: hofForGoat.playerCareer?.championships || 0,
      wins:          player.raceWins    || 0,
      podiums:       player.podiums     || 0,
      points:        player.totalPoints || 0,
    }) : 0;
    if (dynastyScore >= 8000) goatUnlocked = 1;
  } catch(_) {}

  // Check if any player driver has reached GOAT tier (97+ rating)
  if (!goatUnlocked) {
    const hasGoatDriver = playerDrivers.some(d => (d.rating || 0) >= 97 || d.tier === "GOAT");
    if (hasGoatDriver) goatUnlocked = 1;
  }

  // Check if player team is all-time leader in wins
  if (!goatUnlocked) {
    try {
      const hofRaw3 = localStorage.getItem("f1_hall_of_fame_v1");
      if (hofRaw3) {
        const h = JSON.parse(hofRaw3);
        const allTimeTeams = Object.values(h.allTimeTeams || {});
        if (allTimeTeams.length > 0) {
          const maxWins = Math.max(...allTimeTeams.map(t => t.wins || 0));
          const playerHofTeam = h.allTimeTeams[player.id];
          if (playerHofTeam && (playerHofTeam.wins || 0) >= maxWins && maxWins > 0) {
            goatUnlocked = 1;
          }
          // All-time leader in championships
          const maxChamps = Math.max(...allTimeTeams.map(t => t.championships || 0));
          if (playerHofTeam && (playerHofTeam.championships || 0) >= maxChamps && maxChamps > 0) {
            goatUnlocked = 1;
          }
        }
      }
    } catch(_) {}
  }

  // Also respect existing GOAT flag if set on the team
  if (player.goatStatus) goatUnlocked = 1;

  return {
    totalWins,
    totalPodiums,
    careerPoints,
    totalChampionships,
    consecutiveChampionships,
    totalEarnings,
    teamValue,
    perfectSeasons,
    winStreak,
    seasonsCompleted,
    hofInductions,
    goatUnlocked,
    greatestTeam: totalChampionships >= 3 && teamValueM >= 500 ? 1 : 0,
  };
};
