// ─── DRIVER TRAITS UI HELPER ─────────────────────────────────────────────────
// Renders driver trait badges with icon + label.  size: "sm" (default) or "lg"
// compact: true = icon only with tooltip, false = icon + label text
function DriverTraitsDisplay({ traits, size = "sm", style = {} }) {
  if (!traits || traits.length === 0) return null;
  const isLg = size === "lg";
  return (
    <div style={{ display:"flex", gap: isLg ? 6 : 4, flexWrap:"wrap", ...style }}>
      {traits.map(tr => {
        const def = TRAIT_DEFS[tr];
        if (!def) return null;
        return (
          <span
            key={tr}
            title={def.desc}
            style={{
              display:"inline-flex", alignItems:"center", gap: isLg ? 4 : 3,
              fontSize: isLg ? 11 : 9,
              padding: isLg ? "3px 9px" : "1px 6px",
              borderRadius: 10,
              background:"rgba(225,6,0,0.10)",
              color:"#ff4d4d",
              border:"1px solid rgba(225,6,0,0.22)",
              cursor:"default",
              whiteSpace:"nowrap",
            }}
          >
            <span style={{ fontSize: isLg ? 13 : 10 }}>{def.icon}</span>
            {tr}
          </span>
        );
      })}
    </div>
  );
}
