  "Racecraft Master":          { icon:"🎯",  desc:"Superior race-craft: perfect lines, timing, and positioning.",    effects:{ racePaceBonus:2, overtakeBonus:1 } },
  "Tyre Whisperer":            { icon:"🛞",  desc:"Manages tyre degradation far better than peers.",                 effects:{ tireDegReduction:2, latePaceBonus:2 } },
