// ─── CONFETTI ────────────────────────────────────────────────────────────────
// PERF: memo + useMemo so piece array is stable across renders
const Confetti = memo(function Confetti() {
  const pieces = useMemo(() => Array.from({length:50}, (_,i) => ({
    id:i,
    left:`${Math.random()*100}%`,
    delay:`${Math.random()*1.2}s`,
    color:["#e10600","#f4d03f","#4fc3f7","#00d25b","#fb8c00","#c084fc","#fff"][Math.floor(Math.random()*7)],
    size: `${5+Math.random()*10}px`,
    dur: `${1.0+Math.random()*1.0}s`,
    shape: Math.random() > 0.5 ? "circle" : "square",
  })), []);
  return (
    <div style={{ position:"fixed", inset:0, pointerEvents:"none", zIndex:500, overflow:"hidden" }}>
      {pieces.map(p => (
        <div key={p.id}
          style={{
            position:"absolute",
            left:p.left, top:-20,
            background:p.color,
            width:p.size, height:p.size,
            borderRadius: p.shape==="circle" ? "50%" : "2px",
            animationDelay:p.delay,
            animationDuration:p.dur,
            animation:`confettiFloat ${p.dur} ease ${p.delay} forwards`,
          }}/>
      ))}
    </div>
  );
});

// ─── AI AUCTION LOGIC ────────────────────────────────────────────────────────
const AI_CONSTRUCTOR_RESERVE = 60;
// Asset protection — AI teams hold back budget specifically to compete on top assets.
const AI_GOAT_DRIVER_RESERVE      = 105; // Reserved for GOAT-tier drivers (97-99 rated)
const AI_ELITE_DRIVER_RESERVE     = 85;  // Reserved for Elite-tier drivers (93-96 rated)
const AI_ELITE_CONSTRUCTOR_RATING = 92; // Constructors rated ≥ this are treated as Elite
const AI_TRACK_RESERVE = 40;
// v88: Lowered from 70 to allow AI to spend down closer to target reserve
const AI_MIN_REMAINING = 15;

// ─── v88: BUDGET RESERVATION SYSTEM ─────────────────────────────────────────
// Before any bid is placed, AI sets aside funds for post-Driver-Auction activity.
// v88: Reserves tightened — AI was holding too much back causing 250M+ end budgets.
// Constructor and track reserves reflect minimum viable bids, not comfortable ones.
// v203: Nudged back up slightly (NOT reverted to the pre-v88 35/25 that caused the
// original hoarding problem). Root cause of the Season-3+ debt spiral was drivers
// draining teams below what a leftover Average-tier constructor / Standard track
// actually costs, forcing fillMissingRosters' guarantee-fill into negative budget.
// The existing catch-up-spending-boost (getAuctionContext/aiSpendingLimit) still
// pushes surplus cash back into bidding, so this small increase should not
// reintroduce chronic hoarding.
const AI_RESERVE_CONSTRUCTOR = 32; // Minimum for Constructor Auction (was 25, pre-v88 was 35)
const AI_RESERVE_TRACK       = 22; // Minimum for Track Auction (was 15, pre-v88 was 25)
const AI_RESERVE_UPGRADES    = 7;  // Mid-season upgrade budget (was 10)

// ─── v88: TARGET END-OF-AUCTION RESERVES BY PERSONALITY ─────────────────────
// AI now plans toward a TARGET RESERVE rather than an EMERGENCY FLOOR.
// The target is how much cash the AI *wants* left after all auctions.
// Aggressive teams spend freely; conservative teams hoard less than before.
const AI_TARGET_RESERVE = {
  aggressive:   { min: 5,  max: 20  }, // Was bankrupting — now 5–20M target
  balanced:     { min: 25, max: 60  }, // Healthy mid-range: 25–60M
  conservative: { min: 50, max: 100 }, // Cautious but not 250M+ hoarders
};

// ─── v88: EMERGENCY BUDGET FLOOR ─────────────────────────────────────────────
// Hard safeguard: AI will NEVER intentionally drop below this threshold during
// any bid, except to complete a mandatory minimum roster (< 2 drivers).
// v88: Lowered from 70 to 15 — the target reserve system handles pacing now.
const AI_EMERGENCY_FLOOR = 15;

// ─── v88: DYNAMIC BUDGET PLANNING ────────────────────────────────────────────
// Computes auction progress context for a team. Used to calibrate spending.
// Returns:
//   remainingDriversNeeded  - how many more drivers the team needs (0-2)
//   remainingAssetsNeeded   - total assets still needed (drivers + constructor + track)
//   remainingLots           - total lots left in queue including current
//   remainingBudgetToSpend  - budget minus target reserve (what's available to spend)
//   auctionProgress         - 0.0 (start) to 1.0 (end)
//   spendingPressure        - 0.0 (none) to 1.0 (max urgency to spend)
//   targetReserve           - the mid-point of the team's target reserve range
function getAuctionContext(team, queue, queueIndex) {
  const personality = team.personality || "balanced";

  // Remaining needs
  const driverCount      = (team.drivers || []).length;
  const remainingDriversNeeded = Math.max(0, MAX_DRIVERS_PER_TEAM - driverCount);
  const needsConstructor = !team.constructor ? 1 : 0;
  const needsTrack       = !team.track ? 1 : 0;
  const remainingAssetsNeeded  = remainingDriversNeeded + needsConstructor + needsTrack;

  // Remaining lots
  const remainingLots = Math.max(1, (queue ? queue.length : 1) - queueIndex);
  const totalLots     = queue ? queue.length : 1;
  const auctionProgress = Math.min(1, queueIndex / Math.max(1, totalLots));

  // Target reserve (mid-point of range)
  const reserveRange    = AI_TARGET_RESERVE[personality] || AI_TARGET_RESERVE.balanced;
  const targetReserve   = Math.round((reserveRange.min + reserveRange.max) / 2);

  // Budget available to spend (above target reserve)
  const remainingBudgetToSpend = Math.max(0, (team.budget || 0) - targetReserve);

  // Spending pressure: how urgently should the team spend?
  // Rises when: lots are running out, team still has assets to buy, team has excess cash.
  let spendingPressure = 0;

  // Pressure from auction progress (escalates in second half)
  if (auctionProgress > 0.5) {
    spendingPressure += (auctionProgress - 0.5) * 1.4; // 0–0.7
  }

  // Pressure from remaining asset needs vs remaining lots
  if (remainingAssetsNeeded > 0 && remainingLots > 0) {
    const needRatio = Math.min(1, remainingAssetsNeeded / Math.max(1, remainingLots));
    spendingPressure += needRatio * 0.5; // 0–0.5
  }

  // Catch-up pressure: team holding too much cash relative to target reserve
  const surplusAboveTarget = (team.budget || 0) - targetReserve;
  const startingBudget = STARTING_BUDGET + AUCTION_GRANT; // 385M
  const surplusRatio = surplusAboveTarget / startingBudget;
  if (surplusRatio > 0.5) {
    spendingPressure += (surplusRatio - 0.5) * 0.8; // extra push when holding huge cash
  }

  spendingPressure = Math.min(1, spendingPressure);

  return {
    remainingDriversNeeded,
    remainingAssetsNeeded,
    remainingLots,
    remainingBudgetToSpend,
    auctionProgress,
    spendingPressure,
    targetReserve,
    reserveRange,
  };
}

// ─── v87: FRANCHISE DRIVER STRATEGY ─────────────────────────────────────────
// Before the Driver Auction each AI team identifies a "franchise target tier" based
// on starting budget. A per-tier monetary reserve is then held exclusively for
// securing at least one driver of that calibre. AI avoids spending this reserve on
// lower-tier drivers before its franchise target has appeared. Once a driver at or
// above the franchise tier is won, the reserve is released and bidding aggression
// drops significantly on all remaining driver lots.
//
// Franchise reserves (held in addition to constructor/track/upgrade reserves):
//   GOAT  reserve = 120M  → targets 97-99 rated drivers
//   Elite reserve =  95M  → targets 93-96 rated drivers
//   Strong reserve=  70M  → targets 88-92 rated drivers
//   (teams below 90M budget target BEST_VALUE — no separate franchise reserve)
//
// Target tiers by starting budget:
//   budget ≥ 180 → GOAT
//   budget ≥ 150 → GOAT_OR_ELITE  (happy with either; reserve = GOAT reserve)
//   budget ≥ 120 → ELITE
//   budget ≥  90 → STRONG
//   else          → BEST_VALUE    (no franchise reserve)
//
// Personality overlay on the reserve:
//   aggressive   → always reserves for their target tier; overpay allowed up to +15%
//   balanced     → reserves for their target tier; moderate ceiling
//   conservative → drops one tier down from the budget-based target; protects budget

const FRANCHISE_RESERVE_GOAT   = 120;
const FRANCHISE_RESERVE_ELITE  =  95;
const FRANCHISE_RESERVE_STAR   =  80;  // v101: Star (91-93) franchise reserve
const FRANCHISE_RESERVE_STRONG =  55;  // v101: Lowered — Strong (88-90) are supporting cast

// Returns the franchise target tier for a team given its CURRENT budget.
// v101: Added STAR tier — every team should aim for at least one 91+ driver.
function getFranchiseTier(team) {
  const budget = team.budget || 0;
  const personality = team.personality || "balanced";

  let tier;
  if (budget >= 180)      tier = "GOAT";
  else if (budget >= 150) tier = "GOAT_OR_ELITE";
  else if (budget >= 120) tier = "ELITE";
  else if (budget >= 90)  tier = "STAR";     // v101: Target Star (91-93) as cornerstone
  else if (budget >= 60)  tier = "STRONG";   // v101: Lower threshold
  else                    tier = "BEST_VALUE";

  // Conservative teams target one tier lower to protect their budget
  if (personality === "conservative") {
    if (tier === "GOAT")              tier = "GOAT_OR_ELITE";
    else if (tier === "GOAT_OR_ELITE") tier = "ELITE";
    else if (tier === "ELITE")        tier = "STAR";
    else if (tier === "STAR")         tier = "STRONG";
    else if (tier === "STRONG")       tier = "BEST_VALUE";
  }

  return tier;
}

// Returns the monetary reserve that should be held back for the franchise driver.
// Returns 0 once the franchise requirement has already been met.
function getFranchiseReserve(team) {
  if (hasFranchiseDriver(team)) return 0; // already secured — release reserve

  const tier = getFranchiseTier(team);
  if (tier === "GOAT" || tier === "GOAT_OR_ELITE") return FRANCHISE_RESERVE_GOAT;
  if (tier === "ELITE")   return FRANCHISE_RESERVE_ELITE;
  if (tier === "STAR")    return FRANCHISE_RESERVE_STAR;    // v101
  if (tier === "STRONG")  return FRANCHISE_RESERVE_STRONG;
  return 0; // BEST_VALUE — no specific reserve
}

// Returns true if the team has already secured a driver that satisfies its
// franchise target tier.  Called before every bid decision.
// v101: STAR tier requires a 91+ driver; STRONG requires any Strong+.
function hasFranchiseDriver(team) {
  const drivers = team.drivers || [];
  const tier = getFranchiseTier(team);
  if (tier === "GOAT") {
    return drivers.some(d => d.tier === "GOAT");
  }
  if (tier === "GOAT_OR_ELITE") {
    return drivers.some(d => d.tier === "GOAT" || d.tier === "Elite");
  }
  if (tier === "ELITE") {
    return drivers.some(d => d.tier === "GOAT" || d.tier === "Elite");
  }
  if (tier === "STAR") {
    // v101: Any 91+ rated driver satisfies the Star franchise requirement
    return drivers.some(d => (d.rating || 0) >= 91);
  }
  if (tier === "STRONG") {
    return drivers.some(d => d.tier === "GOAT" || d.tier === "Elite" || d.tier === "Strong");
  }
  // BEST_VALUE: any driver counts
  return drivers.length > 0;
}

// Returns true when the current auction item matches or exceeds the team's
// franchise target tier — i.e. this is the kind of driver the reserve was saved for.
function isFranchiseTargetDriver(team, item) {
  if (item.type !== "driver") return false;
  const tier = getFranchiseTier(team);
  if (tier === "GOAT")            return item.tier === "GOAT";
  if (tier === "GOAT_OR_ELITE")   return item.tier === "GOAT" || item.tier === "Elite";
  if (tier === "ELITE")           return item.tier === "GOAT" || item.tier === "Elite";
  if (tier === "STAR")            return (item.rating || 0) >= 91;  // v101: Star+ (91+) targets
  if (tier === "STRONG")          return item.tier === "GOAT" || item.tier === "Elite" || item.tier === "Strong";
  return true; // BEST_VALUE — anything goes
}

// Returns true when bidding on this driver would spend the franchise reserve
// wastefully on a lower tier before the target has appeared.
// AI should heavily suppress spending in this case.
function isSpendsReserveOnWrongTier(team, item) {
  if (item.type !== "driver") return false;
  if (hasFranchiseDriver(team)) return false;  // already done — no reservation in force
  const reserve = getFranchiseReserve(team);
  if (reserve === 0) return false;             // BEST_VALUE — no restriction

  // If this lot IS the franchise target it's fine to bid
  if (isFranchiseTargetDriver(team, item)) return false;

  // It's a lower-tier driver while the franchise reserve is still active —
  // only flag this if the team wouldn't still have the full reserve left after bidding.
  // Specifically: block spending that would leave < reserve remaining.
  const marketHigh = getItemMarketRange(item).high;
  const remainingAfterBid = team.budget - marketHigh;
  return remainingAfterBid < reserve;
}

function isGOATAsset(item) {
  if (item.type === "driver") return item.tier === "GOAT";
  return false;
}
function isEliteAsset(item) {
  if (item.type === "driver")      return item.tier === "Elite";
  if (item.type === "constructor") return (item.rating || 0) >= AI_ELITE_CONSTRUCTOR_RATING;
  if (item.type === "track")       return item.tier === "Legendary";
  return false;
}
function isStrongAsset(item) {
  if (item.type === "driver")      return item.tier === "Strong";
  if (item.type === "constructor") return (item.rating || 0) >= 84 && (item.rating || 0) < AI_ELITE_CONSTRUCTOR_RATING;
  if (item.type === "track")       return item.tier === "Premium";
  return false;
}

// v101: Star sub-tier within Strong — drivers rated 91-92.
// These are the "cornerstone" drivers that every AI team should pursue.
function isStarDriver(item) {
  return item.type === "driver" && item.tier === "Strong" && (item.rating || 0) >= 91;
}

// v101: Hard bid limits by driver tier — AI teams must respect these ceilings.
// Aggressive teams may exceed by up to 3M in a final head-to-head bidding war only.
const DRIVER_HARD_BID_LIMITS = {
  GOAT:    178,   // GOAT (97-99): target 140-175M, hard limit 178M
  Elite:   145,   // Elite (93-96): target 100-140M, hard limit 145M
  Star:    105,   // Star (91-93): target 70-100M, hard limit 105M
  Strong:  75,    // Strong (88-90): target 45-70M, hard limit 75M
  Average: 48,    // Average (85-87): target 20-45M, hard limit 48M
  Weak:    23,    // Depth (<85): target 5-20M, hard limit 23M
};

// Returns the hard bid limit for a driver item based on its tier and rating.
function getDriverHardBidLimit(item) {
  if (item.type !== "driver") return Infinity;
  if (item.tier === "GOAT")    return DRIVER_HARD_BID_LIMITS.GOAT;
  if (item.tier === "Elite")   return DRIVER_HARD_BID_LIMITS.Elite;
  if (isStarDriver(item))      return DRIVER_HARD_BID_LIMITS.Star;
  if (item.tier === "Strong")  return DRIVER_HARD_BID_LIMITS.Strong;
  if (item.tier === "Average") return DRIVER_HARD_BID_LIMITS.Average;
  return DRIVER_HARD_BID_LIMITS.Weak;
}

// v101: Check if an AI team lacks a cornerstone driver (91+ rated).
function hasCornerstoneDriver(team) {
  const drivers = team.drivers || [];
  return drivers.some(d => (d.rating || 0) >= 91);
}

// ─── v112: DYNAMIC AUCTION AGGRESSION ESCALATION ─────────────────────────────
// Detects cash-hoarding AI teams that lack a franchise driver and temporarily
// elevates their bidding personality when their strategy is failing.
//
// hasFranchiseDriverForEscalation: returns TRUE when the team's best driver
// is rated 90+. Intentionally NOT the complex tier-based hasFranchiseDriver —
// a team with a 90+89 pair should NOT enter escalation.
function hasFranchiseDriverForEscalation(team) {
  const drivers = team.drivers || [];
  return drivers.some(d => (d.rating || 0) >= 90);
}

// Returns the effective personality for bidding decisions, incorporating
// escalation upgrades when a team is hoarding cash without a franchise driver.
//
// Stages (overall auction progress, based on total queue):
//   Stage 1 (>60%): Balanced→Aggressive, Conservative→Balanced
//   Stage 2 (>80%): All personalities→Aggressive
//   Stage 3 (>90%): All→Aggressive + valuation *= 1.05 (returned via escalationValMult)
//
// Returns { effectivePersonality, escalationValMult, escalationStage }
// where escalationValMult is 1.05 at Stage 3, 1.0 otherwise.
//
// Safeguards — escalation is NEVER applied when:
//   • Team already has a franchise driver (best rating 90+)
//   • Team's driver roster is already full
//   • Team's budget is at or near the emergency floor (≤ threshold for the stage)
function getEscalationState(team, queue, queueIndex) {
  const naturalPersonality = team.personality || "balanced";

  // Recovery condition: team already has a franchise driver or full roster
  if (hasFranchiseDriverForEscalation(team)) {
    return { effectivePersonality: naturalPersonality, escalationValMult: 1.0, escalationStage: 0 };
  }
  const driverCount = (team.drivers || []).length;
  if (driverCount >= MAX_DRIVERS_PER_TEAM) {
    return { effectivePersonality: naturalPersonality, escalationValMult: 1.0, escalationStage: 0 };
  }

  // Compute overall auction progress
  const totalLots = Math.max(1, queue ? queue.length : 1);
  const auctionProgress = Math.min(1, (queueIndex || 0) / totalLots);

  const budget = team.budget || 0;

  // ── Stage 3: Desperation (>90%, budget >100M) ───────────────────────────────
  if (auctionProgress > 0.90 && budget > 100) {
    // Safeguard: near emergency floor check (budget must stay > EMERGENCY_FLOOR + 15)
    if (budget > AI_EMERGENCY_FLOOR + 15) {
      return { effectivePersonality: "aggressive", escalationValMult: 1.05, escalationStage: 3 };
    }
  }

  // ── Stage 2: High urgency (>80%, budget >120M) ─────────────────────────────
  if (auctionProgress > 0.80 && budget > 120) {
    if (budget > AI_EMERGENCY_FLOOR + 15) {
      return { effectivePersonality: "aggressive", escalationValMult: 1.0, escalationStage: 2 };
    }
  }

  // ── Stage 1: Moderate escalation (>60%, budget >150M) ──────────────────────
  if (auctionProgress > 0.60 && budget > 150) {
    if (budget > AI_EMERGENCY_FLOOR + 15) {
      let escalatedPersonality = naturalPersonality;
      if (naturalPersonality === "balanced")     escalatedPersonality = "aggressive";
      else if (naturalPersonality === "conservative") escalatedPersonality = "balanced";
      // aggressive teams already behave aggressively — no change needed
      return { effectivePersonality: escalatedPersonality, escalationValMult: 1.0, escalationStage: 1 };
    }
  }

  // No escalation
  return { effectivePersonality: naturalPersonality, escalationValMult: 1.0, escalationStage: 0 };
}

// ─── v102: PRE-AUCTION CORNERSTONE TARGET ASSIGNMENT ─────────────────────────
// Before the Driver Auction begins, every AI team is assigned exactly one
// primary cornerstone target (a 91+ driver). Targets are spread across the
// league to avoid excessive pile-ups on the same driver.
//
// Assignment priority:
//   Strongest AI teams → GOAT targets
//   Remaining teams    → Elite targets
//   Remaining teams    → Star targets
//   No driver assigned to more than 2 teams
//
// "Strongest" is determined by personality then budget:
//   aggressive > balanced > conservative; within same personality, higher budget first.
function assignCornerstoneTargets(aiTeams, driverPool) {
  if (!aiTeams.length || !driverPool.length) return;

  // Separate cornerstone drivers by tier
  const goats  = driverPool.filter(d => d.tier === "GOAT").sort((a, b) => (b.rating || 0) - (a.rating || 0));
  const elites = driverPool.filter(d => d.tier === "Elite").sort((a, b) => (b.rating || 0) - (a.rating || 0));
  const stars  = driverPool.filter(d => d.tier === "Strong" && (d.rating || 0) >= 91).sort((a, b) => (b.rating || 0) - (a.rating || 0));

  // Sort AI teams: aggressive first, then balanced, then conservative; within same personality by budget desc
  const personalityRank = { aggressive: 0, balanced: 1, conservative: 2 };
  const sorted = [...aiTeams].sort((a, b) => {
    const pa = personalityRank[a.personality] ?? 1;
    const pb = personalityRank[b.personality] ?? 1;
    if (pa !== pb) return pa - pb;
    return (b.budget || 0) - (a.budget || 0);
  });

  // Track how many teams are assigned to each driver (max 2)
  const driverAssignmentCount = {};

  function assignFromPool(team, pool) {
    for (const driver of pool) {
      const count = driverAssignmentCount[driver.id] || 0;
      if (count < 2) {
        team.cornerstoneTargetId = driver.id;
        driverAssignmentCount[driver.id] = count + 1;
        return true;
      }
    }
    return false;
  }

  // Phase 1: Assign GOAT targets to strongest teams
  const goatTeamCount = Math.min(sorted.length, goats.length * 2);
  for (let i = 0; i < goatTeamCount; i++) {
    assignFromPool(sorted[i], goats);
  }

  // Phase 2: Assign Elite targets to remaining teams
  let remaining = sorted.slice(goatTeamCount);
  for (const team of remaining) {
    if (!team.cornerstoneTargetId) {
      assignFromPool(team, elites);
    }
  }

  // Phase 3: Assign Star targets to any still-unassigned teams
  remaining = sorted.filter(t => !t.cornerstoneTargetId);
  for (const team of remaining) {
    if (!team.cornerstoneTargetId) {
      assignFromPool(team, stars);
    }
  }

  // Safety: if any team still unassigned, broaden to any 91+ driver
  remaining = sorted.filter(t => !t.cornerstoneTargetId);
  const allCornerstones = driverPool.filter(d => (d.rating || 0) >= 91).sort((a, b) => (b.rating || 0) - (a.rating || 0));
  for (const team of remaining) {
    assignFromPool(team, allCornerstones);
  }
}

// v102: Reassign cornerstone target when a team's assigned target is purchased
// by another team. Searches for: 1) another GOAT, 2) then Elite, 3) then Star
// that is still available in the auction queue.
function reassignCornerstoneTarget(team, auctionQueue, queueIndex) {
  if (!team.isAI) return;
  if (hasCornerstoneDriver(team)) {
    team.cornerstoneTargetId = null; // Already secured — no target needed
    return;
  }

  // Drivers still available in the auction (not yet presented or unsold)
  const remaining = auctionQueue.slice(queueIndex || 0).filter(q => q.type === "driver");
  // Also include any unsold drivers that were already passed
  const availableDrivers = remaining;

  const goats  = availableDrivers.filter(d => d.tier === "GOAT").sort((a, b) => (b.rating || 0) - (a.rating || 0));
  const elites = availableDrivers.filter(d => d.tier === "Elite").sort((a, b) => (b.rating || 0) - (a.rating || 0));
  const stars  = availableDrivers.filter(d => d.tier === "Strong" && (d.rating || 0) >= 91).sort((a, b) => (b.rating || 0) - (a.rating || 0));

  // Pick the best available, preferring GOAT > Elite > Star
  const candidates = [...goats, ...elites, ...stars];
  if (candidates.length > 0) {
    team.cornerstoneTargetId = candidates[0].id;
  } else {
    // No 91+ drivers left — target the best available driver
    const bestRemaining = availableDrivers.sort((a, b) => (b.rating || 0) - (a.rating || 0));
    team.cornerstoneTargetId = bestRemaining.length > 0 ? bestRemaining[0].id : null;
  }
}

// v102: Check if a driver item is this team's assigned cornerstone target
function isCornerstoneTarget(team, item) {
  return item.type === "driver" && team.cornerstoneTargetId && item.id === team.cornerstoneTargetId;
}

// v102: League Health Validation — called after Driver Auction completes.
// Returns a stats object with key metrics for evaluating auction balance.
function validateLeagueHealth(teams, driverPool) {
  const aiTeams = teams.filter(t => t.isAI);
  const teamsWithout91 = aiTeams.filter(t => !hasCornerstoneDriver(t));

  // Calculate average sale prices by tier from purchasePrices
  const soldDrivers = [];
  aiTeams.forEach(t => {
    (t.drivers || []).forEach(d => {
      const price = t.purchasePrices?.[d.id] || 0;
      if (price > 0) soldDrivers.push({ ...d, salePrice: price });
    });
  });

  const avgPrice = (arr) => arr.length ? Math.round(arr.reduce((s, d) => s + d.salePrice, 0) / arr.length) : 0;

  const goatSales  = soldDrivers.filter(d => d.tier === "GOAT");
  const eliteSales = soldDrivers.filter(d => d.tier === "Elite");
  const starSales  = soldDrivers.filter(d => d.tier === "Strong" && (d.rating || 0) >= 91);

  // Unsold cornerstone drivers
  const soldIds = new Set(soldDrivers.map(d => d.id));
  const unsold91 = driverPool.filter(d => (d.rating || 0) >= 91 && !soldIds.has(d.id));

  // Remaining budgets
  const budgets = aiTeams.map(t => t.budget || 0);
  const avgBudget = budgets.length ? Math.round(budgets.reduce((a, b) => a + b, 0) / budgets.length) : 0;

  return {
    teamsWithout91Plus: teamsWithout91.length,
    teamsWithout91Names: teamsWithout91.map(t => t.name),
    avgGOATPrice: avgPrice(goatSales),
    avgElitePrice: avgPrice(eliteSales),
    avgStarPrice: avgPrice(starSales),
    unsold91Count: unsold91.length,
    avgRemainingBudget: avgBudget,
    maxRemainingBudget: Math.max(...budgets, 0),
    minRemainingBudget: Math.min(...budgets, 0),
  };
}

// ─── TIER-BASED AUCTION ORDERING ──────────────────────────────────────────────
// Drivers:      GOAT (97-99) -> Elite (93-96) -> Strong (88-92) -> Average (82-87) -> Weak (76-81)
// Constructors: Elite (random) -> Strong (random) -> Average (random) -> Weak (random)
// Tracks:       Legendary/Elite (random) -> Premium/Strong (random) -> Average -> Weak
// Randomisation within each tier ensures variety while guaranteeing top assets
// appear while all teams still have their full budget available.
function orderByTier(items) {
  if (!items.length) return [];

  const type = items[0].type;

  if (type === "driver") {
    // v101: Six tiers: GOAT -> Elite -> Star(91-92) -> Strong(88-90) -> Average -> Weak
    // Star drivers appear before non-Star Strong so teams bid on them with fuller budgets.
    const goat    = fisherYatesShuffle(items.filter(d => d.tier === "GOAT"));
    const elite   = fisherYatesShuffle(items.filter(d => d.tier === "Elite"));
    const star    = fisherYatesShuffle(items.filter(d => d.tier === "Strong" && (d.rating||0) >= 91));
    const strong  = fisherYatesShuffle(items.filter(d => d.tier === "Strong" && (d.rating||0) < 91));
    const average = fisherYatesShuffle(items.filter(d => d.tier === "Average"));
    const weak    = fisherYatesShuffle(items.filter(d => !["GOAT","Elite","Strong","Average"].includes(d.tier)));
    return [...goat, ...elite, ...star, ...strong, ...average, ...weak];
  }

  if (type === "constructor") {
    // Five tiers based on rating bands matching new target ranges
    const legendary = fisherYatesShuffle(items.filter(c => (c.rating||0) >= 92));  // Legendary (92+)
    const elite     = fisherYatesShuffle(items.filter(c => (c.rating||0) >= 88 && (c.rating||0) < 92)); // Elite (88-91)
    const strong    = fisherYatesShuffle(items.filter(c => (c.rating||0) >= 84 && (c.rating||0) < 88)); // Strong (84-87)
    const average   = fisherYatesShuffle(items.filter(c => (c.rating||0) >= 80 && (c.rating||0) < 84)); // Average (80-83)
    const weak      = fisherYatesShuffle(items.filter(c => (c.rating||0) < 80));  // Weak (<80)
    return [...legendary, ...elite, ...strong, ...average, ...weak];
  }

  if (type === "track") {
    // Three source tiers map to four ordered groups:
    // Legendary -> Elite, Premium -> Strong, Standard -> Average/Weak (split by half for variety)
    // Standard tracks (all basePrice 20, powerUps 4) are identical in tier, so split them
    // into an "average" first-half and "weak" second-half after shuffling for variety.
    const elite    = fisherYatesShuffle(items.filter(t => t.tier === "Legendary"));
    const strong   = fisherYatesShuffle(items.filter(t => t.tier === "Premium"));
    const standard = fisherYatesShuffle(items.filter(t => t.tier === "Standard"));
    const mid      = Math.ceil(standard.length / 2);
    const average  = standard.slice(0, mid);
    const weak     = standard.slice(mid);
    return [...elite, ...strong, ...average, ...weak];
  }

  return fisherYatesShuffle(items);
}

// ─── MARKET VALUATION ENGINE v78 ─────────────────────────────────────────────
// Every asset class has a fixed market-value range that is the target for final
// sale prices.  AI personality shifts the team's individual valuation within
// (or just above) that range, but the *market* range itself is hard-anchored so
// results are predictable and never bargain-basement for elite assets.
//
// Target ranges (used as the authoritative reference throughout):
//   GOAT Drivers   (97-99): $105M – $130M
//   Elite Drivers  (93-96):  $85M – $110M
//   Strong Drivers (88-92):  $48M –  $83M
//   Average Drivers(82-87):  $15M –  $45M
//   Weak Drivers   (76-81):   $5M –  $20M
//
//   Legendary/Elite Constructors (≥91): $55M – $75M
//   Strong Constructors  (86-90):       $35M – $55M
//   Average Constructors (80-85):       $18M – $35M
//   Weak Constructors    (<80):          $8M – $20M
//
//   Legendary Tracks:  $55M – $75M
//   Premium Tracks:    $30M – $55M
//   Standard Tracks:   $10M – $30M

// Returns { low, mid, high } absolute dollar range for the item (budget-independent).
function getItemMarketRange(item) {
  if (!item) return { low: 5, mid: 10, high: 20 };

  if (item.type === "driver") {
    // v101: Driver auction rebalance — market ranges aligned to target price bands.
    // GOAT (97-99): 140M-175M target, Elite (93-96): 100M-140M, Star (91-92): 70M-100M,
    // Strong (88-90): 45M-70M, Average (82-87): 20M-45M, Depth (<82): 5M-20M.
    // Rating-based fine-grain within tier for price variation.
    const r = item.rating || 0;
    if (item.tier === "GOAT") {
      // 99→~175, 98→~165, 97→~145
      const base = r >= 99 ? 170 : r >= 98 ? 160 : 145;
      return { low: base - 10, mid: base, high: base + 10 };
    }
    if (item.tier === "Elite") {
      // 96→~135, 95→~120, 94→~110, 93→~105
      const base = r >= 96 ? 135 : r >= 95 ? 120 : r >= 94 ? 110 : 105;
      return { low: base - 10, mid: base, high: base + 10 };
    }
    // Star sub-tier: Strong drivers rated 91-92
    if (item.tier === "Strong" && r >= 91) {
      // 92→~85, 91→~75
      const base = r >= 92 ? 85 : 75;
      return { low: base - 8, mid: base, high: base + 8 };
    }
    if (item.tier === "Strong") {
      // 90→~65, 88→~55
      const base = r >= 90 ? 65 : 55;
      return { low: base - 10, mid: base, high: base + 10 };
    }
    if (item.tier === "Average") return { low: 20,  mid: 32,  high: 45  };
    /* Weak / Depth (<82) */    return { low: 5,   mid: 12,  high: 20  };
  }

  if (item.type === "constructor") {
    const r = item.rating || 0;
    if (r >= 92) return { low: 60, mid: 70, high: 80 }; // Legendary (92+): 60M-80M
    if (r >= 88) return { low: 50, mid: 60, high: 70 }; // Elite (88-91): 50M-70M
    if (r >= 84) return { low: 35, mid: 45, high: 55 }; // Strong (84-87): 35M-55M
    if (r >= 80) return { low: 20, mid: 30, high: 40 }; // Average (80-83): 20M-40M
    /* Weak (<80) */return { low: 10, mid: 17, high: 25 }; // Weak: 10M-25M
  }

  if (item.type === "track") {
    if (item.tier === "Legendary") return { low: 60, mid: 70, high: 80 }; // Legendary: 60M-80M
    if (item.tier === "Premium")   return { low: 40, mid: 50, high: 60 }; // Premium: 40M-60M
    /* Standard */                 return { low: 20, mid: 30, high: 40 }; // Standard: 20M-40M
  }

  return { low: 5, mid: 10, high: 20 };
}

// Returns the ABSOLUTE maximum this AI team will ever bid on the given item.
// This is the true hard ceiling — the team drops out the moment the live price
// exceeds this value.
//
// Formula: personalityValuation = range.mid + spread * personalityFactor
// where spread = (range.high - range.mid).
// Then overpay layer on top:
//   aggressive:   +12% above range.high  (can exceed valuation)
//   balanced:     + 5% above range.high
//   conservative: at range.mid (rarely reaches range.high)
//
// Additionally a per-team random "wallet" factor (±8%) is baked in once per lot
// so that not all aggressive teams have identical ceilings.
//
// v87: Franchise Driver Strategy boost/suppress added:
//   - franchise target driver: ceiling raised +3–15% by personality
//   - wrong-tier driver while reserve active: ceiling crushed to 40%
//   - franchise already met: ceiling reduced to 80% (stacks with roster discount)
// v86: Three additional protections updated:
//   1. Spendable budget cap (budget − totalReserve) prevents overspend.
//      Constructor reserve raised 50→60M, track reserve raised 30→40M.
//   2. Dynamic spending protection: thresholds raised 90→110, 70→90, 55→70
//      so AI pulls back much earlier in the auction.
//   3. Roster-aware discount: unchanged.
//   4. Emergency floor: AI_EMERGENCY_FLOOR raised 60→70.
// v88: aiSpendingLimit — now incorporates dynamic budget planning and spending pressure.
//
// Key changes from v87:
//   1. Dynamic spending thresholds now use TARGET RESERVE (personality-calibrated) not
//      hardcoded 110/90/70. Aggressive teams can spend low; conservative teams pull back
//      relative to their own target reserve.
//   2. Catch-up spending: when team holds excess cash vs target reserve, ceiling rises
//      to push excess into the auction rather than holding it through end-of-auction.
//   3. Spending pressure multiplier applied late in auction to keep competition alive.
//   4. Emergency floor uses AI_EMERGENCY_FLOOR (15) not 70, so teams can spend down.
//   5. Franchise strategy logic preserved from v87.
function aiSpendingLimit(team, item, queue, queueIndex) {
  const range = getItemMarketRange(item);
  const personality = team.personality || "balanced";

  // Base valuation = somewhere in the range based on personality
  let valuation;
  if (personality === "aggressive") {
    valuation = range.high;                               // starts at ceiling
  } else if (personality === "balanced") {
    valuation = range.mid + (range.high - range.mid) * 0.5; // midpoint→high
  } else {
    valuation = range.mid;                                 // conservative = mid
  }

  // Overpay cap: how far above their own valuation they're allowed to go
  const overpayFactor = personality === "aggressive" ? 1.12
                      : personality === "balanced"   ? 1.05
                      :                                1.00;

  // Per-team wallet variance: ±8% so teams feel individually distinct
  const idSeed = (team.id || "x").split("").reduce((a, c) => a + c.charCodeAt(0), 0);
  const walletVariance = 1 + ((idSeed % 17) - 8) / 100; // range: 0.92 – 1.08

  let hardCap = Math.round(valuation * overpayFactor * walletVariance);

  // Never let the cap exceed the absolute range ceiling * overpay factor
  const absoluteCeiling = Math.round(range.high * overpayFactor);
  hardCap = Math.min(hardCap, absoluteCeiling);

  // ── v88: Catch-up Spending Boost ─────────────────────────────────────────────
  // When AI is holding much more cash than their target reserve, raise the ceiling
  // to inject that surplus back into the auction. This prevents 250M+ end budgets.
  const ctx = getAuctionContext(team, queue || [], queueIndex || 0);
  if (ctx.spendingPressure > 0.3) {
    // Scale ceiling up by up to 20% based on how much pressure exists
    const pressureBoost = 1 + ctx.spendingPressure * 0.20;
    hardCap = Math.round(hardCap * pressureBoost);
    // Also allow exceeding absolute ceiling when spending pressure is high
    const boostedCeiling = Math.round(range.high * overpayFactor * pressureBoost);
    hardCap = Math.min(hardCap, boostedCeiling);
  }

  // ── v87: Franchise Driver Strategy ───────────────────────────────────────────
  if (item.type === "driver") {
    const franchiseTarget = isFranchiseTargetDriver(team, item);
    const franchiseMet    = hasFranchiseDriver(team);

    if (!franchiseMet && franchiseTarget) {
      const franchiseBoost = personality === "aggressive" ? 1.15
                           : personality === "balanced"   ? 1.08
                           :                                1.03;
      hardCap = Math.round(hardCap * franchiseBoost);
    } else if (!franchiseMet && isSpendsReserveOnWrongTier(team, item)) {
      // v129: Raised 0.62→0.75 to match the getAIValuation suppression fix. The spending
      // ceiling must track the valuation ceiling — if valuation is at 0.75× but the cap
      // is still 0.62×, the cap overrides and crushes bids back down. Both gates must
      // move together to allow meaningful competition on lower-tier drivers.
      hardCap = Math.round(hardCap * 0.75);
      if (item.basePrice && hardCap < item.basePrice) {
        hardCap = item.basePrice + 1; // allow exactly one increment above opening bid
      }
    } else if (franchiseMet) {
      // v130: Raised 0.80→0.88 to match the getAIValuation franchiseMet change (0.75→0.85).
      // Both gates must move together — if the cap is tighter than the valuation, it silently
      // overrides and produces the same zero-bid outcome the valuation fix was meant to cure.
      hardCap = Math.round(hardCap * 0.88);
    }
  }

  // ── v102: Cornerstone Target Pursuit — spending limit boost ──────────────────
  // When bidding on the assigned cornerstone target, raise the spending limit.
  // Hard bid limits (enforced later) still cap the final result.
  if (item.type === "driver" && !hasCornerstoneDriver(team) && isCornerstoneTarget(team, item)) {
    const targetBoost = personality === "aggressive" ? 1.12
                      : personality === "balanced"   ? 1.08
                      :                                1.05;
    hardCap = Math.round(hardCap * targetBoost);
  }

  // ── v88: Dynamic Spending Protection — calibrated to TARGET RESERVE ───────────
  // Pull back bidding ceiling as budget approaches the team's target reserve.
  // Thresholds are now relative to target reserve, not hardcoded dollar amounts.
  // This prevents aggressive teams going bankrupt while allowing them to spend freely.
  if (item.type === "driver") {
    const targetMin = (AI_TARGET_RESERVE[personality] || AI_TARGET_RESERVE.balanced).min;
    const budgetAboveTarget = (team.budget || 0) - targetMin;

    if (budgetAboveTarget < 80)  hardCap = Math.round(hardCap * 0.85);
    if (budgetAboveTarget < 50)  hardCap = Math.round(hardCap * 0.70);
    if (budgetAboveTarget < 30)  hardCap = Math.round(hardCap * 0.50);
    if (budgetAboveTarget < 15)  hardCap = Math.round(hardCap * 0.25); // near bankrupt
  }

  // ── v84: Roster-Aware Discount ────────────────────────────────────────────────
  if (item.type === "driver") {
    const roster = team.drivers || [];
    const eliteOrGOATCount = roster.filter(d => d.tier === "GOAT" || d.tier === "Elite").length;
    const strongOrAboveCount = roster.filter(d =>
      d.tier === "GOAT" || d.tier === "Elite" || d.tier === "Strong"
    ).length;

    if (eliteOrGOATCount >= 2) {
      hardCap = Math.round(hardCap * 0.55);
    } else if (strongOrAboveCount >= 3) {
      hardCap = Math.round(hardCap * 0.65);
    }
  }

  // ── v88: Spendable budget cap via target-reserve-aware aiAvailableBudget ──────
  const spendable = aiAvailableBudget(team, item, queue, queueIndex);
  let affordableCap = Math.min(spendable, hardCap);

  // ── v101: Hard bid limit enforcement for drivers ─────────────────────────────
  // AI teams must respect tier-based hard bid ceilings. Aggressive teams may
  // exceed by up to 3M only during a final head-to-head bidding war (handled
  // at bid-time in processAIBids/computeAIBidDecision), but the spending limit
  // itself never exceeds the hard limit.
  if (item.type === "driver") {
    const hardBidLimit = getDriverHardBidLimit(item);
    affordableCap = Math.min(affordableCap, hardBidLimit);
  }

  // ── v88: Emergency floor hard safeguard (lowered to AI_EMERGENCY_FLOOR = 15) ──
  // AI must never drop below the personality target reserve minimum, except for
  // mandatory roster fills (fewer than MAX_DRIVERS_PER_TEAM drivers).
  const driverCount = (team.drivers || []).length;
  const isMandatoryRosterFill = item.type === "driver" && driverCount < MAX_DRIVERS_PER_TEAM;
  if (!isMandatoryRosterFill) {
    const floorProtected = Math.min(affordableCap, team.budget - AI_EMERGENCY_FLOOR);
    return Math.max(floorProtected, 0);
  }

  return Math.max(affordableCap, 0);
}

// v88: Budget availability — now uses TARGET RESERVE system instead of fixed reserves.
// This is the primary fix for AI teams finishing with 250M+ surplus cash.
//
// The target reserve is personality-calibrated (5-20M aggressive, 25-60M balanced,
// 50-100M conservative). AI protects its target minimum, not a hard floor.
//
// In addition, per-phase minimums are respected to ensure AI always has enough
// for constructor / track phases, layered on top of the target reserve.
//
// v87 franchise reserve logic is preserved as an overlay.
function aiAvailableBudget(team, item, queue, queueIndex) {
  const personality = team.personality || "balanced";

  // Base: protect the target reserve minimum (personality-calibrated end-of-auction goal)
  const reserveRange  = AI_TARGET_RESERVE[personality] || AI_TARGET_RESERVE.balanced;
  const targetReserve = reserveRange.min; // Use minimum of range as protected floor

  let reserve = targetReserve;

  // Per-phase minimums: protect enough for later auction phases.
  // Layered on top of target reserve so the team can still compete.
  if (!team.constructor && item?.type !== "constructor") {
    reserve = Math.max(reserve, targetReserve + AI_RESERVE_CONSTRUCTOR);
  }
  if (!team.track && item?.type !== "track") {
    reserve = Math.max(reserve, targetReserve + AI_RESERVE_TRACK);
  }
  // Always protect upgrade budget on top of target
  reserve = Math.max(reserve, targetReserve + AI_RESERVE_UPGRADES);

  // v87: Franchise reserve — protect funds for the target tier franchise driver.
  // Only applied when bidding on drivers and the franchise driver has not yet been secured.
  if (item?.type === "driver" && !hasFranchiseDriver(team)) {
    const franchiseReserve = getFranchiseReserve(team);
    if (franchiseReserve > 0 && !isFranchiseTargetDriver(team, item)) {
      reserve = Math.max(reserve, targetReserve + franchiseReserve);
    }
  }

  // Hard floor guarantee — never let spendable go below zero
  return Math.max(0, team.budget - reserve);
}

function aiRosterPriority(team, item) {
  const driverCount = (team.drivers||[]).length;
  // ROSTER FIX: hard cap at MAX_DRIVERS_PER_TEAM senior drivers — never bid for more
  if (item.type === "driver" && driverCount < MAX_DRIVERS_PER_TEAM) return 4;
  if (item.type === "constructor" && !team.constructor) return 3;
  if (item.type === "track" && !team.track) return 2;
  // driverCount >= MAX_DRIVERS_PER_TEAM: team is full — return 0 (won't bid) for ALL personalities
  if (item.type === "driver" && driverCount >= MAX_DRIVERS_PER_TEAM) return 0;
  return 0;
}

// ─── VALUATION ENGINE v101 ────────────────────────────────────────────────────
// Returns the AI team's INTERNAL ceiling price — the absolute most they will
// pay.  Derived from market ranges calibrated to new target price bands.
//
// Personality goals (v101):
//   aggressive:   Prioritize GOAT drivers, engage in premium bidding wars,
//                 spend closer to maximum valuation.
//   balanced:     Prioritize Elite drivers, aggressively pursue remaining 91+
//                 drivers, avoid major overpayments.
//   conservative: Focus on value, still target at least one 91+ driver,
//                 prefer Stars if Elite prices become excessive.
function getAIValuation(team, item, auctionContext) {
  const priority = aiRosterPriority(team, item);
  if (priority === 0) return 0;

  const range = getItemMarketRange(item);
  const { isMini, queue, queueIndex } = auctionContext;

  // ── v112: Dynamic Aggression Escalation ─────────────────────────────────────
  // Determine if this team's strategy is failing (hoarding cash, no franchise driver).
  // Only applies to driver lots; constructors/tracks use natural personality.
  const escalation = item.type === "driver"
    ? getEscalationState(team, queue, queueIndex)
    : { effectivePersonality: team.personality || "balanced", escalationValMult: 1.0, escalationStage: 0 };
  const effectivePersonality = escalation.effectivePersonality;

  // Per-team wallet: stable ±6% variance so teams feel distinct.
  const idSeed = (team.id || "x").split("").reduce((a, c) => a + c.charCodeAt(0), 0);
  const wallet = 1 + ((idSeed % 13) - 6) / 100; // 0.94 – 1.06

  let valuation;
  if (effectivePersonality === "aggressive") {
    // Aggressive: values near top of range, willing to push into high territory
    // GOAT drivers: spend up to range.high; others: range.high * 1.02
    const overpay = item.type === "driver" && isGOATAsset(item) ? 1.00
                  : 1.02 + ((idSeed % 2) / 100); // 1.02–1.03 for non-GOAT
    valuation = Math.round(range.high * overpay * wallet);
  } else if (effectivePersonality === "balanced") {
    // Balanced: values in upper-mid range, chases Elites and Stars
    const midToHigh = range.mid + (range.high - range.mid) * 0.65;
    valuation = Math.round(midToHigh * wallet);
  } else {
    // Conservative: values at or slightly below mid. Focus on value.
    valuation = Math.round(range.mid * 0.95 * wallet);
  }

  // Urgency: if fewer items of this type remain, teams get a push.
  // v101: Top-tier drivers (GOAT/Elite/Star) now ALSO get urgency boosts
  // since they are scarce cornerstone assets.
  if (queue && queue.length) {
    const remaining = queue.slice(queueIndex + 1).filter(q => q.type === item.type).length;
    if (remaining === 0) valuation = Math.round(valuation * 1.18);
    else if (remaining <= 2) valuation = Math.round(valuation * 1.09);
  }

  // Essential item boost: if this is the only type the team still needs
  if (priority >= 3) valuation = Math.round(valuation * 1.10);

  // ── v87: Franchise Driver Valuation ─────────────────────────────────────────
  if (item.type === "driver") {
    const franchiseMet    = hasFranchiseDriver(team);
    const franchiseTarget = isFranchiseTargetDriver(team, item);

    if (!franchiseMet && franchiseTarget) {
      const franchiseValBoost = team.personality === "aggressive" ? 1.15
                              : team.personality === "balanced"   ? 1.10
                              :                                     1.05;
      valuation = Math.round(valuation * franchiseValBoost);
    } else if (!franchiseMet && isSpendsReserveOnWrongTier(team, item)) {
      // v129: Raised 0.60→0.75 so suppressed valuations land meaningfully above basePrice,
      // enabling real bidding competition on Average/Weak/Strong(88-90) drivers even when
      // a franchise reserve is active. The 0.60 floor still produced valuations too close
      // to basePrice for conservative teams, causing zero bid activity past the opening bid.
      // Floor at basePrice remains as hard guarantee.
      valuation = Math.round(valuation * 0.75);
      if (item.basePrice && valuation < item.basePrice) {
        valuation = item.basePrice;
      }
    } else if (franchiseMet) {
      // v130: Raised 0.75→0.85. The 0.75 discount stacked with progressive budget-caution
      // multipliers (up to ×0.50 near target reserve) was collapsing effective valuations on
      // Strong/Average/Weak drivers to below basePrice, causing zero competition on those lots.
      // 0.85 preserves the "franchise met = less interested in secondary drivers" intent while
      // keeping valuations high enough to survive budget-caution without crashing to zero.
      valuation = Math.round(valuation * 0.85);
    }
  }

  // ── v102: Cornerstone Target Pursuit ────────────────────────────────────────
  // When the driver being auctioned is this team's assigned cornerstone target,
  // boost valuation by personality-dependent amount. Never exceeds hard bid limits.
  if (item.type === "driver" && !hasCornerstoneDriver(team) && isCornerstoneTarget(team, item)) {
    const targetBoost = team.personality === "aggressive" ? 1.15
                      : team.personality === "balanced"   ? 1.12
                      :                                     1.08;
    valuation = Math.round(valuation * targetBoost);
  }

  // ── v101: Cornerstone Driver Urgency ────────────────────────────────────────
  // If a team has reached 50% of the Driver Auction without a 91+ driver,
  // increase valuation and bid interest for remaining 91+ drivers.
  // This ensures every team attempts to secure a cornerstone driver.
  if (item.type === "driver" && !hasCornerstoneDriver(team)) {
    if (queue && queue.length) {
      const driverLots = queue.filter(q => q.type === "driver").length;
      const pastDriverLots = queue.slice(0, queueIndex || 0).filter(q => q.type === "driver").length;
      const driverProgress = driverLots > 0 ? pastDriverLots / driverLots : 0;

      // 50% through driver auction without a 91+ driver — increase urgency
      if (driverProgress >= 0.50 && (item.rating || 0) >= 91) {
        const urgencyBoost = team.personality === "aggressive"   ? 1.12
                           : team.personality === "balanced"     ? 1.10
                           :                                       1.08;
        valuation = Math.round(valuation * urgencyBoost);
      }

      // ── v101: Panic Mode ──────────────────────────────────────────────────
      // Final phase of driver auction, still no 91+ driver — further boost
      // valuation and bid activity for remaining Star/Elite/GOAT drivers.
      // Hard bid limits MUST still be respected (enforced in aiSpendingLimit).
      if (driverProgress >= 0.75 && (item.rating || 0) >= 91) {
        const panicBoost = team.personality === "aggressive"   ? 1.08
                         : team.personality === "balanced"     ? 1.06
                         :                                       1.05;
        valuation = Math.round(valuation * panicBoost);
      }
    }
  }

  // ── v89: Auction Pressure Scaling ───────────────────────────────────────────
  if (queue && queue.length) {
    const totalLots = queue.length;
    const progress = Math.min(1, (queueIndex || 0) / Math.max(1, totalLots));
    let pressureMult = 1;
    if (progress >= 0.85)      pressureMult = 1.25;
    else if (progress >= 0.70) pressureMult = 1.15;
    else if (progress >= 0.50) pressureMult = 1.08;
    valuation = Math.round(valuation * pressureMult);
  }

  // ── v89: Catch-up Spending — but v101: capped by hard bid limits for drivers ──
  // Non-driver items keep the catch-up boost. For drivers, the hard bid limit
  // already prevents unrealistic prices, so catch-up is gentler.
  const cashOnHand = team.budget || 0;
  if (item.type === "driver") {
    // v101: Driver catch-up is softer — hard bid limits prevent irrational bids.
    // A team with lots of cash still values drivers more, but respects ceilings.
    if (cashOnHand >= 200)      valuation = Math.round(valuation * 1.12);
    else if (cashOnHand >= 150) valuation = Math.round(valuation * 1.08);
    else if (cashOnHand >= 100) valuation = Math.round(valuation * 1.05);
  } else {
    if (cashOnHand >= 200)      valuation = Math.round(valuation * 1.30);
    else if (cashOnHand >= 150) valuation = Math.round(valuation * 1.20);
    else if (cashOnHand >= 100) valuation = Math.round(valuation * 1.10);
  }

  // Hard cap: never exceed aiSpendingLimit (includes v101 hard bid limits for drivers)
  const cap = aiSpendingLimit(team, item, queue, queueIndex);

  // ── v112: Stage 3 Desperation valuation bump (+5%) ──────────────────────────
  // Applied AFTER all other boosts, BEFORE hard caps. Small urgency signal only.
  // Hard bid limits always cap the final result regardless.
  if (item.type === "driver" && escalation.escalationValMult > 1.0) {
    valuation = Math.round(valuation * escalation.escalationValMult);
  }

  // Absolute ceiling — for drivers, this IS the hard bid limit.
  // For non-drivers, use the existing formula.
  if (item.type === "driver") {
    // v101: Hard bid limit is the absolute ceiling for drivers. No catch-up
    // multiplier can push past it. Aggressive overpay (up to +3M) is handled
    // at bid-time, not in the valuation/spending limit.
    return Math.min(valuation, cap, getDriverHardBidLimit(item));
  }

  let absoluteMaxMult = 1.05;
  if (cashOnHand >= 200)      absoluteMaxMult = 1.05 * 1.30;
  else if (cashOnHand >= 150) absoluteMaxMult = 1.05 * 1.20;
  else if (cashOnHand >= 100) absoluteMaxMult = 1.05 * 1.10;
  const absoluteMax = Math.round(range.high * absoluteMaxMult);

  return Math.min(valuation, cap, absoluteMax);
}

// ─── RETENTION COST HELPERS ───────────────────────────────────────────────────
// Driver: purchase price + flat fee by tier. Constructor: purchase price + $5M.
// Used by both the player RetentionScreen and AI retention logic.
function driverRetentionCost(purchasePrice, tier) {
  const flat = tier === "GOAT"    ? 15
             : tier === "Elite"   ? 12
             : tier === "Strong"  ? 10
             : tier === "Average" ?  8
             :                       5; // Weak
  return Math.round(purchasePrice + flat);
}
function constructorRetentionCost(purchasePrice) {
  return Math.round(purchasePrice + 5);
}

// ─── DRIVER RETENTION SCORING (AI) ─────────────────────────────────────────────
// Season-performance-driven retention decisions, built on the same shape as the
// Constructor Retention system below (tier → chance, personality shift, roll)
// but with the chance itself derived from how the driver actually performed
// this season instead of a fixed tier band. Does NOT touch retention cost,
// the auction system, or the retention UI — only how the AI decides yes/no.

// Rough season-points baseline for "met expectations" per tier over a full
// RACES_PER_SEASON campaign. Deliberately flat per tier (no per-team
// adjustment) — team strength is handled separately as its own "team context"
// factor below, matching the brief's factor list one-for-one.
const DRIVER_TIER_EXPECTED_POINTS = { GOAT: 260, Elite: 170, Strong: 100, Average: 50, Weak: 18 };
// Same rating bands used elsewhere (patchDriverRatings) — reused here only for
// a small in-tier nudge (a 96-rated Elite reads slightly better than a 93).
const DRIVER_TIER_RATING_BAND = { GOAT: [97, 99], Elite: [93, 96], Strong: [88, 92], Average: [82, 87], Weak: [76, 81] };
// Retention-chance anchors per tier: poor / average / good season → base
// chance, before personality and team-context shifts. "poor" is new territory
// versus the old fixed lo/hi band — it's what lets a disastrous season put
// even a GOAT's contract at real risk, per the brief.
const DRIVER_TIER_RETENTION_CURVE = {
  GOAT:    { poor: 0.32, average: 0.72, good: 0.96 },
  Elite:   { poor: 0.22, average: 0.52, good: 0.87 },
  Strong:  { poor: 0.16, average: 0.50, good: 0.76 },
  Average: { poor: 0.10, average: 0.24, good: 0.58 },
  Weak:    { poor: 0.03, average: 0.10, good: 0.30 },
};

// Aggregates each driver's just-completed-season wins/podiums/points/starts
// from allRaceResults. Safe to use even though the completed season's entries
// are compressed to the top-10 finishers per race (endSeason does this to
// bound save size) — only top-10 finishers ever score points, so points/wins/
// podiums are unaffected by the compression. "racesScored" (top-10 finishes ÷
// races run) stands in for Consistency and Average Finish, since exact
// finishing position for cars outside the top 10 isn't preserved in history.
function getSeasonDriverStats(allRaceResults, seasonNum) {
  const stats = {};
  const seasonRaces = (allRaceResults || []).filter(r => r.race?.season === seasonNum);
  seasonRaces.forEach(r => {
    (r.results || []).forEach((res, idx) => {
      if (!res || !res.driverId) return;
      if (!stats[res.driverId]) stats[res.driverId] = { wins: 0, podiums: 0, points: 0, racesScored: 0 };
      const s = stats[res.driverId];
      s.points += res.points || 0;
      if (idx === 0) s.wins++;
      if (idx <= 2) s.podiums++;
      s.racesScored++;
    });
  });
  return { stats, racesRun: seasonRaces.length };
}

// Maps a driver's completed season onto a 0..1 score where 0.5 = "met
// expectations" for their tier, 0 = a disastrous season, 1 = a career year.
// Folds in every factor from the brief: championship position, wins, podiums,
// total points, consistency (via points-scoring rate), driver rating (within
// tier), driver tier (via the expected-points baseline), age, form, and value
// for money (purchase price vs points delivered).
function computeDriverSeasonScore(driver, seasonStats, racesRun, anchorPrice, driverChampRank) {
  const tier = driver.tier || "Weak";
  const rating = driver.rating || 70;
  const age = driver.age || 26;
  const formScore = FORM_VALUES[driver.form] ?? 0; // -3..+3

  const expected = DRIVER_TIER_EXPECTED_POINTS[tier] || 40;
  const seasonPts = seasonStats ? seasonStats.points : (driver.currentSeasonPoints ?? driver.seasonPoints ?? 0);
  const pointsRatio = expected > 0 ? seasonPts / expected : 1;

  const winBonus    = Math.min(0.35, (seasonStats?.wins    || 0) * 0.10);
  const podiumBonus = Math.min(0.20, (seasonStats?.podiums || 0) * 0.04);

  // Consistency / average finish proxy — only judged when we actually have
  // race data for this driver this season; a fresh signing with no starts
  // yet is treated as neutral rather than penalized as "inconsistent".
  const races = racesRun || RACES_PER_SEASON;
  const consistency = seasonStats && races > 0 ? seasonStats.racesScored / races : 0.5;

  const [tLo, tHi] = DRIVER_TIER_RATING_BAND[tier] || [76, 81];
  const ratingWithin = tHi > tLo ? Math.max(0, Math.min(1, (rating - tLo) / (tHi - tLo))) : 0.5;

  // Value for money: an expensive bust is judged more harshly than a cheap
  // one; an expensive driver who's still delivering gets no penalty for the
  // price tag — a great season stands on its own, regardless of what was
  // paid for it (matches the brief's example directly).
  const baselinePrice = driverBasePriceFromRating(rating) || 10;
  const priceRatio = anchorPrice > 0 ? anchorPrice / Math.max(1, baselinePrice) : 1;
  let valueMod = 0;
  if (pointsRatio < 0.85) valueMod = -Math.min(0.12, Math.max(0, priceRatio - 1) * 0.10);
  else if (pointsRatio >= 1.0) valueMod = Math.min(0.08, Math.max(0, 1 - priceRatio) * 0.10);

  // Age curve — young drivers earn development patience even in a rough
  // season, veterans need results to justify keeping their seat.
  let ageAdj = 0;
  if (age <= 23) ageAdj = 0.08;
  else if (age <= 25) ageAdj = 0.04;
  else if (age >= 37) ageAdj = -0.10;
  else if (age >= 34) ageAdj = -0.05;

  // Championship position — finishing near the top of the standings carries
  // prestige beyond what the raw points term already captures.
  let champPosBonus = 0;
  if (driverChampRank === 1) champPosBonus = 0.10;
  else if (driverChampRank <= 3) champPosBonus = 0.06;
  else if (driverChampRank <= 6) champPosBonus = 0.03;

  const score = 0.5
    + (pointsRatio - 1) * 0.30
    + winBonus + podiumBonus
    + (consistency - 0.5) * 0.14
    + (ratingWithin - 0.5) * 0.06
    + valueMod
    + champPosBonus
    + formScore * 0.015
    + ageAdj;

  return Math.max(0, Math.min(1, score));
}

// Interpolates the tier's poor/average/good anchors using the 0..1 score.
function driverTierRetentionChance(tier, score) {
  const c = DRIVER_TIER_RETENTION_CURVE[tier] || DRIVER_TIER_RETENTION_CURVE.Weak;
  if (score <= 0.5) return c.poor + (c.average - c.poor) * (score / 0.5);
  return c.average + (c.good - c.average) * ((score - 0.5) / 0.5);
}

// ─── CORE AI BIDDING ─────────────────────────────────────────────────────────
// v86: Dynamic spending thresholds raised to 110/90/70 (was 90/70/55) to match
// aiSpendingLimit and computeAIBidDecision, ensuring AI pulls back earlier.
// v85: Hardened with the same three protections that computeAIBidDecision uses:
//   1. Emergency floor guard — skips bid if (budget − nextBid) < AI_EMERGENCY_FLOOR
//      (mandatory roster fills of < 2 drivers are exempt).
//   2. Dynamic spending protection — scales bidChance down as budget falls
//      (×0.85 below $110M, ×0.70 below $90M, ×0.50 below $70M) for driver items.
//   3. Final bid floor check — aborts after increment computation if the incremented
//      bid would still breach the emergency floor.
// These guards were already in computeAIBidDecision (live auction path) but were
// missing from processAIBids (batch/pass-based auction path), leaving a window
// where AI teams could still over-spend during certain auction transitions.
function processAIBids(auction, newBid, newBidder) {
  let bid = newBid, bidder = newBidder;
  const item = auction.currentItem;
  const log = [...auction.log];
  const passed = new Set(auction.passedTeams);
  const sortedAI = auction.teams.filter(t => t.isAI && !passed.has(t.id));

  // v101: Count active bidders for head-to-head detection
  const activeBidders = sortedAI.filter(t => {
    const p = aiRosterPriority(t, item);
    if (p === 0) return false;
    if (p === 1 && item.type === "driver" && !isGOATAsset(item) && !isEliteAsset(item) && !isStarDriver(item)
        && t.personality !== "aggressive") return false;
    return true;
  }).length;
  const isHeadToHead = activeBidders <= 2;

  sortedAI.forEach(team => {
    const priority = aiRosterPriority(team, item);
    if (priority === 0) { passed.add(team.id); return; }

    // ── v112: Dynamic Aggression Escalation ──────────────────────────────────
    // Derive effective personality for this team on this lot.
    const escalation = item.type === "driver"
      ? getEscalationState(team, auction.queue, auction.queueIndex)
      : { effectivePersonality: team.personality || "balanced", escalationStage: 0 };
    const effectivePersonality = escalation.effectivePersonality;

    // v101: Star drivers are now "top tier" for bid eligibility
    const isTopDriver = item.type === "driver" && (isGOATAsset(item) || isEliteAsset(item) || isStarDriver(item));
    if (priority === 1 && !isTopDriver && effectivePersonality !== "aggressive") {
      passed.add(team.id); return;
    }

    const val = getAIValuation(team, item, auction);
    const spendLimit = aiSpendingLimit(team, item, auction.queue, auction.queueIndex);
    const nextBid = bid + 1;
    const canAfford = team.budget > nextBid && nextBid <= spendLimit;
    const worthIt   = val > bid;

    // ── v85: Emergency floor guard ────────────────────────────────────────────
    if (item.type === "driver") {
      const driverCount = (team.drivers || []).length;
      const isMandatoryFill = driverCount < MAX_DRIVERS_PER_TEAM;
      if (!isMandatoryFill && (team.budget - nextBid) < AI_EMERGENCY_FLOOR) {
        passed.add(team.id);
        return;
      }
    }

    // ── v101: Bid probability by tier (v112: uses effectivePersonality) ──────
    let bidChance;
    if (isGOATAsset(item)) {
      bidChance = effectivePersonality === "aggressive" ? 0.99
                : effectivePersonality === "balanced"   ? 0.94
                :                                         0.84;
    } else if (isEliteAsset(item) && item.type === "driver") {
      bidChance = effectivePersonality === "aggressive" ? 0.97
                : effectivePersonality === "balanced"   ? 0.92
                :                                         0.82;
    } else if (isStarDriver(item)) {
      // v101: Star (91-93) drivers — high priority for all personalities
      bidChance = effectivePersonality === "aggressive" ? 0.94
                : effectivePersonality === "balanced"   ? 0.88
                :                                         0.78;
    } else if (isEliteAsset(item) && item.type === "constructor") {
      bidChance = effectivePersonality === "aggressive" ? 0.97
                : effectivePersonality === "balanced"   ? 0.92
                :                                         0.82;
    } else if (isEliteAsset(item)) {
      bidChance = effectivePersonality === "aggressive" ? 0.98
                : effectivePersonality === "balanced"   ? 0.94
                :                                         0.87;
    } else if (isStrongAsset(item) && item.type === "driver") {
      // v130: Raised 0.82/0.68/0.55 → 0.86/0.74/0.60. With the franchiseMet valuation
      // now at 0.85× (up from 0.75×), worthIt passes more reliably. These base values
      // ensure Strong non-Star drivers have enough active bidders to hit the 80%+ sell target.
      bidChance = team.personality === "aggressive" ? 0.86
                : team.personality === "balanced"   ? 0.74
                :                                     0.60;
    } else if (isStrongAsset(item) && item.type === "constructor") {
      bidChance = team.personality === "aggressive" ? 0.86
                : team.personality === "balanced"   ? 0.72
                :                                     0.58;
    } else if (isStrongAsset(item)) {
      bidChance = team.personality === "aggressive" ? 0.92
                : team.personality === "balanced"   ? 0.80
                :                                     0.65;
    } else if (priority >= 3) {
      // v130: For drivers (Average/Weak), raised balanced 0.76→0.80 and conservative 0.56→0.62.
      // These tiers have already seen teams' budgets depleted by GOAT/Elite spending, which
      // triggers progressive caution multipliers. Raising the base gives enough headroom.
      if (item.type === "driver") {
        bidChance = team.personality === "aggressive" ? 0.90
                  : team.personality === "balanced"   ? 0.80
                  :                                     0.62;
      } else {
        bidChance = team.personality === "aggressive" ? 0.90
                  : team.personality === "balanced"   ? 0.76
                  :                                     0.56;
      }
    } else if (priority === 2) {
      bidChance = team.personality === "aggressive" ? 0.75
                : team.personality === "balanced"   ? 0.58
                :                                     0.40;
    } else {
      bidChance = team.personality === "aggressive" ? 0.60 : 0.30;
    }

    // ── v101: Cornerstone Driver Urgency — bid probability boost ────────────
    // If team lacks a 91+ driver and this is one, increase bid frequency
    if (item.type === "driver" && !hasCornerstoneDriver(team) && (item.rating || 0) >= 91) {
      if (auction.queue && auction.queue.length) {
        const driverLots = auction.queue.filter(q => q.type === "driver").length;
        const pastDriverLots = auction.queue.slice(0, auction.queueIndex || 0).filter(q => q.type === "driver").length;
        const driverProgress = driverLots > 0 ? pastDriverLots / driverLots : 0;

        if (driverProgress >= 0.50) {
          bidChance = Math.min(1, bidChance * 1.15);
        }
        // Panic mode: final phase without cornerstone
        if (driverProgress >= 0.75) {
          bidChance = Math.min(1, bidChance * 1.10);
        }
      }
    }

    // ── v102: Cornerstone Target Pursuit — +20% bid frequency ──────────────────
    if (item.type === "driver" && !hasCornerstoneDriver(team) && isCornerstoneTarget(team, item)) {
      bidChance = Math.min(1, bidChance * 1.20);
    }

    // ── v102: Satisfaction System — remove urgency/panic boosts once secured ──
    if (item.type === "driver" && hasCornerstoneDriver(team)) {
      // Team already has a cornerstone — reduce bid frequency on other 91+ drivers
      if ((item.rating || 0) >= 91) {
        bidChance *= 0.70; // Anti-hoarding: less interested in additional 91+ drivers
      }
    }

    // ── v102: Anti-Hoarding Rule ────────────────────────────────────────────────
    // Teams with a 91+ driver get reduced valuation and bid chance on other 91+ drivers.
    // Exception: aggressive teams may still pursue GOAT drivers if they don't have one.
    if (item.type === "driver" && hasCornerstoneDriver(team) && (item.rating || 0) >= 91) {
      const hasGOAT = (team.drivers || []).some(d => d.tier === "GOAT");
      const isGOATItem = isGOATAsset(item);
      if (isGOATItem && !hasGOAT && team.personality === "aggressive") {
        // Aggressive teams without a GOAT may still chase one — but reduced enthusiasm
        bidChance *= 0.85;
      } else {
        // All other cases: significant reduction to prevent hoarding
        bidChance *= 0.70;
      }
    }

    // ── v89: Dynamic spending protection — calibrated to TARGET RESERVE ──────
    if (item.type === "driver") {
      const reserveRange = AI_TARGET_RESERVE[team.personality] || AI_TARGET_RESERVE.balanced;
      const aboveTarget = (team.budget || 0) - reserveRange.min;
      if (aboveTarget < 80) bidChance *= 0.85;
      if (aboveTarget < 50) bidChance *= 0.70;
      if (aboveTarget < 25) bidChance *= 0.50;
    }

    // ── v89: Auction Pressure Scaling ────────────────────────────────────────
    const totalLots = auction.queue ? auction.queue.length : 1;
    const progress = Math.min(1, (auction.queueIndex || 0) / Math.max(1, totalLots));
    if (progress >= 0.85)      bidChance = Math.min(1, bidChance * 1.30);
    else if (progress >= 0.70) bidChance = Math.min(1, bidChance * 1.18);
    else if (progress >= 0.50) bidChance = Math.min(1, bidChance * 1.08);

    // ── v101: Driver catch-up spending (gentler for drivers, respects hard limits) ──
    const cashOnHand = team.budget || 0;
    if (item.type === "driver") {
      if (cashOnHand >= 200)      bidChance = Math.min(1, bidChance * 1.20);
      else if (cashOnHand >= 150) bidChance = Math.min(1, bidChance * 1.15);
      else if (cashOnHand >= 100) bidChance = Math.min(1, bidChance * 1.08);
    } else {
      if (cashOnHand >= 200)      bidChance = Math.min(1, bidChance * 1.45);
      else if (cashOnHand >= 150) bidChance = Math.min(1, bidChance * 1.30);
      else if (cashOnHand >= 100) bidChance = Math.min(1, bidChance * 1.15);
    }

    if (canAfford && worthIt && Math.random() < bidChance) {
      let increment;
      if (isGOATAsset(item)) {
        const r = Math.random();
        increment = team.personality === "aggressive"
          ? (r > 0.60 ? 7 : r > 0.30 ? 6 : 5)
          : (r > 0.55 ? 6 : r > 0.25 ? 5 : 4);
      } else if (isEliteAsset(item) && item.type === "driver") {
        const r = Math.random();
        increment = team.personality === "aggressive"
          ? (r > 0.55 ? 6 : r > 0.25 ? 5 : 4)
          : (r > 0.60 ? 5 : r > 0.30 ? 4 : 3);
      } else if (isStarDriver(item)) {
        // v101: Star driver increments — 3-5M to push toward 70-100M range
        const r = Math.random();
        increment = team.personality === "aggressive"
          ? (r > 0.50 ? 5 : r > 0.20 ? 4 : 3)
          : (r > 0.50 ? 4 : r > 0.20 ? 3 : 2);
      } else if (isEliteAsset(item) && item.type === "constructor") {
        const r = Math.random();
        increment = team.personality === "aggressive"
          ? (r > 0.55 ? 5 : r > 0.25 ? 4 : 3)
          : (r > 0.55 ? 4 : r > 0.25 ? 3 : 2);
      } else if (isEliteAsset(item)) {
        const r = Math.random();
        increment = team.personality === "aggressive"
          ? (r > 0.55 ? 6 : r > 0.25 ? 5 : 4)
          : (r > 0.55 ? 5 : r > 0.25 ? 4 : 3);
      } else if (isStrongAsset(item) && item.type === "driver") {
        increment = team.personality === "aggressive" ? (Math.random() > 0.45 ? 3 : 2) : (Math.random() > 0.50 ? 3 : 2);
      } else if (isStrongAsset(item) && item.type === "constructor") {
        increment = team.personality === "aggressive" ? (Math.random() > 0.45 ? 3 : 2) : (Math.random() > 0.55 ? 3 : 2);
      } else if (isStrongAsset(item)) {
        increment = team.personality === "aggressive" ? (Math.random() > 0.45 ? 4 : 3) : (Math.random() > 0.50 ? 3 : 2);
      } else {
        increment = team.personality === "aggressive" ? (Math.random() > 0.55 ? 2 : 1) : 1;
      }

      let finalBid = bid + increment;

      // ── v101: Hard bid limit enforcement for drivers ──────────────────────
      // Aggressive teams may exceed hard limit by up to 3M in a head-to-head
      // bidding war only. All other teams respect the hard limit strictly.
      if (item.type === "driver") {
        const hardLimit = getDriverHardBidLimit(item);
        const aggressiveOverpay = (team.personality === "aggressive" && isHeadToHead) ? 3 : 0;
        const effectiveLimit = hardLimit + aggressiveOverpay;
        if (finalBid > effectiveLimit) {
          finalBid = Math.min(effectiveLimit, finalBid);
          if (finalBid <= bid) { passed.add(team.id); return; }
        }
      }

      // ── v85: Final emergency floor check ─────────────────────────────────
      if (item.type === "driver") {
        const driverCount = (team.drivers || []).length;
        if (driverCount >= MAX_DRIVERS_PER_TEAM && (team.budget - finalBid) < AI_EMERGENCY_FLOOR) {
          passed.add(team.id);
          return;
        }
      }
      bid = finalBid;
      bidder = team.id;
      log.push({ text:`${team.name} bids ${bid}M`, type:"ai" });
    } else {
      passed.add(team.id);
    }
  });

  return { bid, bidder, passed, log };
}

// ─── MISSING FUNCTION DEFINITIONS (v171 fixes) ───────────────────────────────

// ─── v193: TRANSFER MARKET VALUATION ENGINE ──────────────────────────────────
// Three distinct concepts, never conflated:
//   • basePrice           — driver's database value. NEVER changes. Auction
//                            starting point only (set in DRIVER_RATINGS /
//                            driverBasePriceFromRating, untouched by this file).
//   • purchasePrice        — what a team actually paid (auction win bid, or
//                            transfer-market fee). Stored on the driver object
//                            wherever a transaction happens (already wired up
//                            throughout the auction/transfer code) and carried
//                            forward season-to-season until the driver is
//                            released back to the pool.
//   • currentMarketValue   — what the driver is worth *right now*, in *this*
//                            career save. Anchored on purchasePrice (falling
//                            back to basePrice only if the driver has never
//                            actually been bought), then adjusted by what has
//                            happened since: rating, age, form, championships,
//                            wins, podiums, recent points, contract status.
//
// A driver bought for 179M should evolve from 179M, not snap back to a 95M
// database number the moment the Sell screen renders.

// tierMarketValue — fallback valuation table, used ONLY when a driver has no
// purchase history yet (e.g. an unowned pool/free-agent driver being shown
// before any team has signed them). Once a driver has a purchasePrice this
// table is never consulted again for that driver.
function tierMarketValue(driver) {
  const tierMV = { GOAT: 90, Elite: 72, Strong: 42, Average: 22, Weak: 10 };
  return tierMV[driver?.tier] ?? Math.round((driver?.rating || 70) * 0.5);
}

// driverValueAnchor — the "anchor" a driver's current value evolves from:
// the price actually paid for them, if any, otherwise their unchanging
// database base value. This is what the rest of the valuation formula
// adjusts up or down — it is never the final number on its own.
function driverValueAnchor(driver) {
  if (!driver) return 10;
  if (typeof driver.purchasePrice === "number" && driver.purchasePrice > 0) {
    return driver.purchasePrice;
  }
  return driver.basePrice ?? driver.baseAuctionPrice ?? tierMarketValue(driver);
}

// driverValueModifier — career/condition swing applied on TOP of the anchor,
// expressed as a fractional change (0.08 = +8%). Every signal here is
// centered at 0 so an untouched driver's value stays close to their anchor;
// the swing only grows as the driver performs (or declines) during the
// career. Components are intentionally additive and individually capped so
// no single stat can blow the value out — but championships + a hot season
// for a young star can still stack into a large premium, matching how real
// auction-driven transfer markets behave.
function driverValueModifier(driver) {
  if (!driver) return 0;
  let modifier = 0;

  // Current hot/cold streak — the most immediate signal of in-season demand.
  const formScore = FORM_VALUES[driver.form] ?? 0; // -3..+3
  modifier += formScore * 0.03; // up to ±9%

  // Recent performance: points actually scored this season.
  const seasonPts = driver.currentSeasonPoints ?? driver.seasonPoints ?? 0;
  modifier += Math.min(0.12, seasonPts * 0.0015); // up to +12%

  // Career achievements compound slowly as a driver's legacy grows.
  modifier += Math.min(0.14, (driver.wins || 0) * 0.006);
  modifier += Math.min(0.08, (driver.podiums || 0) * 0.0025);
  modifier += Math.min(0.18, (driver.championships || 0) * 0.06);

  // Age curve — young drivers with real upside appreciate, veterans decline.
  const age = driver.age || 26;
  const rating = driver.rating || 70;
  if (age <= 23 && rating >= 88) modifier += 0.10;       // young high-potential star
  else if (age <= 24) modifier += 0.04;                   // generic youth premium
  else if (age >= 35) modifier -= 0.10;                   // late-career decline
  else if (age >= 32) modifier -= 0.04;

  // Rating drift since signing, when we know the rating at purchase time —
  // growth/decline relative to the player a team actually paid for.
  if (typeof driver.purchaseRating === "number") {
    modifier += (rating - driver.purchaseRating) * 0.012;
  }

  // Contract status — more years remaining on the deal holds value better
  // than a driver entering their final season.
  if (typeof driver.contractYears === "number") {
    if (driver.contractYears <= 0) modifier -= 0.05;
    else if (driver.contractYears >= 2) modifier += 0.02;
  }

  // Clamp the overall swing so a single season moves the needle believably
  // (matches the "poor/average/excellent season" bands) without letting a
  // driver's value run away from reality in either direction.
  return Math.max(-0.30, Math.min(0.45, modifier));
}

// computeDriverMarketValue — the single source of truth for "what is this
// driver worth right now". Used everywhere in the Transfer Market (buy/sell/
// free agents/negotiations) and by Team HQ's Market Values tab.
function computeDriverMarketValue(driver) {
  if (!driver) return 10;
  const anchor = driverValueAnchor(driver);
  const modifier = driverValueModifier(driver);
  return Math.max(5, Math.round(anchor * (1 + modifier)));
}

// stampDriverPurchase — the single place that records what a team actually
// paid for a driver at the moment of acquisition (auction win, transfer-market
// buy, free-agent signing, or contract retention). Sets purchasePrice AND
// purchaseRating (the rating-drift signal in driverValueModifier was reading
// purchaseRating but nothing ever wrote it — that growth/decline component
// was always inert) and immediately snapshots currentMarketValue/marketValue
// so a driver's value reflects what was paid from the instant the deal is
// done, rather than waiting for the next end-of-season updateMarketValues()
// pass. Without this, any screen reading the persisted field (instead of
// calling computeDriverMarketValue live) shows a driver as worth their
// unchanged database basePrice right after a big auction win.
function stampDriverPurchase(driver, price) {
  if (!driver) return driver;
  const stamped = {
    ...driver,
    purchasePrice: price,
    purchaseRating: driver.rating,
    baseAuctionPrice: driver.baseAuctionPrice ?? driver.basePrice,
  };
  const mv = computeDriverMarketValue(stamped);
  return {
    ...stamped,
    marketValue: mv,
    currentMarketValue: mv,
    prevMarketValue: mv,
    lastCalculatedMarketValue: mv,
  };
}

// computeMarketValueRange — the band of offers a driver could realistically
// fetch right now, centered on computeDriverMarketValue(). Used for the
// "Estimated Offers: XM – YM" display on the Sell screen. Volatile (hot/cold
// form) drivers get a slightly wider band, since their price is less settled.
function computeMarketValueRange(driver) {
  const mv = computeDriverMarketValue(driver);
  const formScore = Math.abs(FORM_VALUES[driver?.form] ?? 0);
  const spread = 0.06 + formScore * 0.01; // ±6% baseline, up to ±9% if form is extreme
  const low = Math.max(5, Math.round(mv * (1 - spread)));
  const high = Math.round(mv * (1 + spread));
  return { low, high };
}

// updateMarketValues — refresh team driver market values after aging/evolution.
// Called in endSeason after ageAndEvolveDrivers so prevMarketValue tracks change.
// Now routes through computeDriverMarketValue so the persisted marketValue
// field (shown on Team HQ's Market Values tab) reflects purchase price and
// career performance instead of resetting to a tier/rating-only number.
function updateMarketValues(teams) {
  return teams.map(team => ({
    ...team,
    drivers: (team.drivers || []).map(d => {
      const mv = computeDriverMarketValue(d);
      const prevMv = d.currentMarketValue ?? d.marketValue ?? mv;
      return {
        ...d,
        prevMarketValue: prevMv,
        marketValue: mv,
        // v193: explicit fields per the purchasePrice/currentMarketValue/
        // lastCalculatedMarketValue persistence contract — kept in sync with
        // the legacy marketValue/prevMarketValue fields above so nothing
        // that already reads those breaks.
        lastCalculatedMarketValue: prevMv,
        currentMarketValue: mv,
      };
    }),
  }));
}

// ─── AI TRANSFER MARKET ENGINE v182 ──────────────────────────────────────────
// Full proactive transfer logic: AI teams can release underperformers and sign
// better free agents — not just fill gaps. Runs at end of every season.
// Safety: never creates duplicates, never exceeds MAX_DRIVERS_PER_TEAM,
// never spends below AI_MIN_REMAINING, preserves all driver IDs and career stats.
//
// v182 enhancements:
//   • Team personality governs target tier (aggressive=GOAT/Elite, conservative=Average/Strong)
//   • Championship-winners very rarely change drivers (≤10% chance per driver)
//   • Last-place teams change more aggressively (70%+ chance at replacement)
//   • Transfer news items carry richer metadata: driverTier, driverAge, driverRating,
//     teamPersonality, seasonRank, signingType for AIDriverMarketScreen display
//   • Target 2–4 total grid changes per season across all AI teams
//   • Aggressive teams can "poach" retained drivers from other AI teams if budget allows
//   • Rookie promotions: conservative teams with budget sometimes sign promising young free agents

// Team emoji map for display in transfer news
const AI_TEAM_EMOJI = {
  aggressive: "🔥",
  balanced:   "⚡",
  conservative: "🌿",
};

// Classify what kind of signing an AI team is making
function aiSigningType(driver, team, seasonRank, totalTeams) {
  const r = driver.rating || 70;
  const age = driver.age || 26;
  const personality = team.personality || "balanced";
  if (r >= 93) return "superstar";
  if (age <= 22 && r >= 78) return "wonderkid";
  if (age <= 24 && r >= 74) return "youngster";
  if (r >= 88) return "star";
  if (seasonRank > totalTeams * 0.7) return "desperation";
  if (personality === "conservative" && age <= 24) return "development";
  return "standard";
}

// Score a driver's value to a specific team (higher = more desirable)
function aiDriverDesirability(driver, team, seasonRank, totalTeams) {
  const r = driver.rating || 70;
  const age = driver.age || 26;
  const pts = driver.currentSeasonPoints || driver.seasonPoints || 0;
  const personality = team.personality || "balanced";

  // Base rating score
  let score = r * 1.2;

  // Age curve — young drivers get a potential bonus, very old get a penalty
  if (age <= 22) score += 12;
  else if (age <= 25) score += 6;
  else if (age <= 28) score += 0;
  else if (age <= 32) score -= 5;
  else if (age <= 35) score -= 14;
  else score -= 24;

  // Season points bonus — drivers who scored heavily this season are more valued
  score += Math.min(20, pts * 0.08);

  // Career wins/podiums add prestige value
  score += Math.min(15, (driver.wins || 0) * 0.6 + (driver.podiums || 0) * 0.15);

  // Trait bonuses
  const traits = driver.traits || [];
  if (traits.includes("Wonderkid") || traits.includes("Fast Learner")) score += 8;
  if (traits.includes("Clutch Performer") || traits.includes("Championship Mentality")) score += 6;
  if (traits.includes("Consistent")) score += 4;
  if (traits.includes("Mentor") && personality === "conservative") score += 6;
  if (traits.includes("Aggressive Overtaker") && personality === "aggressive") score += 5;

  // Personality modifier
  if (personality === "aggressive") {
    // Aggressive teams want the best rating regardless of age/cost
    score += (r - 80) * 0.5;
    // Bonus for truly elite drivers
    if (r >= 93) score += 20;
    if (r >= 88) score += 10;
  } else if (personality === "conservative") {
    // Conservative teams want value: young + cheap + developing
    score += age <= 25 ? 10 : age >= 32 ? -10 : 0;
    // Prefer not to pay for stars they can't develop
    if (r >= 93) score -= 8;
  } else {
    // Balanced: slight preference for mid-career (25-30) sweet spot
    score += age >= 25 && age <= 30 ? 5 : 0;
  }

  // Championship-winning teams are conservative — don't fix what isn't broken
  if (seasonRank === 1) score -= 10; // slight discount on "need to change"

  return score;
}

// Evaluate whether an AI team should release a driver this off-season
function aiShouldRelease(driver, team, freeAgents, seasonRank, totalTeams) {
  const personality = team.personality || "balanced";
  const age = driver.age || 26;
  const r = driver.rating || 70;
  const pts = driver.currentSeasonPoints || driver.seasonPoints || 0;
  const totalDrivers = team.drivers?.length || 0;

  // Never release if it would leave team with no drivers
  if (totalDrivers <= 1) return false;

  // Championship winners almost never make changes — they have the formula working
  if (seasonRank === 1) {
    // Only if driver is truly terrible AND very old
    return age >= 38 && r < 78 && pts < 5;
  }

  let releaseScore = 0;

  // Older declining drivers are more likely to be released
  if (age >= 40) releaseScore += 60;
  else if (age >= 38) releaseScore += 45;
  else if (age >= 36) releaseScore += 28;
  else if (age >= 34) releaseScore += 14;

  // Low performance drivers are candidates
  if (pts === 0 && seasonRank > totalTeams * 0.6) releaseScore += 22;
  else if (pts < 5) releaseScore += 10;

  // Low-rated drivers in bottom half of grid
  if (r < 76 && seasonRank > totalTeams * 0.5) releaseScore += 28;
  else if (r < 80 && seasonRank > totalTeams * 0.7) releaseScore += 18;
  else if (r < 82) releaseScore += 7;

  // Bottom teams are much more likely to make changes
  const bottomThird = seasonRank > totalTeams * 0.67;
  if (bottomThird) releaseScore += 12;

  // Personality thresholds — aggressive teams churn more readily
  const threshold = personality === "aggressive" ? 30
                  : personality === "balanced"   ? 45
                  :                                65; // conservative is hardest to convince

  // Check if there's a meaningfully better free agent available before releasing
  const improvement = freeAgents.some(fa =>
    !team.drivers.some(d => d.id === fa.id) &&
    fa.rating > r + 3 &&
    computeDriverMarketValue(fa) <= (team.budget - AI_MIN_REMAINING)
  );

  return releaseScore >= threshold && improvement;
}

// Get a team-specific emoji for transfer news display
function getTeamTransferEmoji(team) {
  if (!team) return "🏎️";
  const name = (team.name || "").toLowerCase();
  // Map common team names to recognisable emojis
  if (name.includes("ferrari") || name.includes("scuderia")) return "🐎";
  if (name.includes("mercedes")) return "⭐";
  if (name.includes("red bull") || name.includes("redbull")) return "🐂";
  if (name.includes("mclaren")) return "🧡";
  if (name.includes("aston")) return "💚";
  if (name.includes("alpine") || name.includes("renault")) return "🔵";
  if (name.includes("williams")) return "🏁";
  if (name.includes("haas")) return "⚙️";
  if (name.includes("alfa") || name.includes("sauber")) return "🔴";
  if (name.includes("rb") || name.includes("toro") || name.includes("racing bulls")) return "🐂";
  // Fall back to personality-based emoji
  return AI_TEAM_EMOJI[team.personality || "balanced"] || "🏎️";
}

// Main AI transfer market function
// Returns { updatedTeams, transfers[], releasedDrivers[] }
function runAITransferMarket(teams, freeAgents) {
  const transfers = [];
  const releasedDrivers = [];
  // Track which free agents have been signed this window
  const signedAgentIds = new Set();

  // Build season standings for context using the LAST completed season
  // Find the highest season index that has points recorded
  let sIdx = 0;
  teams.forEach(t => {
    const sp = t.seasonPoints || [];
    for (let i = sp.length - 1; i >= 0; i--) {
      if (sp[i] > 0 && i > sIdx) { sIdx = i; break; }
    }
  });

  const rankedTeams = [...teams].sort((a, b) =>
    (b.seasonPoints?.[sIdx] || 0) - (a.seasonPoints?.[sIdx] || 0)
  );
  const totalTeams = teams.length;

  // Sort teams: process championship team last (most conservative), bottom teams first (most likely to change)
  const sortedTeams = [...teams].sort((a, b) => {
    if (!a.isAI && !b.isAI) return 0;
    if (!a.isAI) return 1;  // player always last
    if (!b.isAI) return -1;
    // Bottom-table teams first
    const rankA = rankedTeams.findIndex(t => t.id === a.id) + 1;
    const rankB = rankedTeams.findIndex(t => t.id === b.id) + 1;
    return rankB - rankA; // higher rank number = lower on table = processed first
  });

  // Target 2–4 total changes across the grid for realism.
  // Bottom teams add pressure for more changes; aggressive teams do too.
  const baseMax = 2 + Math.floor(Math.random() * 3); // 2–4
  const maxTotalChanges = baseMax;
  let totalChanges = 0;

  // Pool of all free agents (grows as AI teams release drivers)
  const availablePool = [...freeAgents];

  const updatedTeams = sortedTeams.map(team => {
    if (!team.isAI) return team;

    const seasonRank = rankedTeams.findIndex(t => t.id === team.id) + 1;
    const t = { ...team, drivers: [...(team.drivers || [])] };
    const personality = t.personality || "balanced";
    const teamEmoji = getTeamTransferEmoji(t);

    // ── PHASE 1: Release evaluation ───────────────────────────────────────────
    // Only consider releasing if we haven't hit the global change cap
    if (totalChanges < maxTotalChanges && t.drivers.length >= 2) {
      // Evaluate each driver for release, worst-rated first
      const driversByScore = [...t.drivers].sort((a, b) =>
        aiDriverDesirability(a, t, seasonRank, totalTeams) -
        aiDriverDesirability(b, t, seasonRank, totalTeams)
      );

      for (const candidate of driversByScore) {
        if (totalChanges >= maxTotalChanges) break;
        if (t.drivers.length <= 1) break; // never leave team stranded

        if (aiShouldRelease(candidate, t, availablePool, seasonRank, totalTeams)) {
          const stripped = { ...candidate };
          delete stripped.purchasePrice;
          delete stripped._releasedFrom;
          t.drivers = t.drivers.filter(d => d.id !== candidate.id);
          availablePool.push(stripped);
          releasedDrivers.push({ ...stripped, _releasedFrom: team.id });

          const cAge = candidate.age || 26;
          const cRating = candidate.rating || 70;
          const releaseReason = cAge >= 36 ? "veteran retirement" :
                                cRating < 78 ? "underperformance" :
                                seasonRank > totalTeams * 0.7 ? "lineup shake-up" :
                                "contract ended";

          transfers.push({
            type: "release",
            driver: candidate.name,
            driverRating: cRating,
            driverAge: cAge,
            driverTier: candidate.tier || "Average",
            fromTeam: t.name,
            teamEmoji,
            teamPersonality: personality,
            toTeam: null,
            fee: 0,
            releaseReason,
            icon: cAge >= 36 ? "🏁" : "👋",
            color: "#a78bfa",
          });
          totalChanges++;
          break; // max 1 release per team per season
        }
      }
    }

    // ── PHASE 2: Sign evaluation ──────────────────────────────────────────────
    const needsDriver = t.drivers.length < MAX_DRIVERS_PER_TEAM;
    // Proactive upgrade: only if we still have budget headroom and change slots
    const canUpgrade = totalChanges < maxTotalChanges && t.drivers.length === MAX_DRIVERS_PER_TEAM && false; // disabled: proactive upgrades handled via release+sign

    if (!needsDriver && !canUpgrade) return t;

    // Build affordable, available candidates from the free-agent pool
    const candidates = availablePool.filter(d => {
      if (signedAgentIds.has(d.id)) return false;
      if (t.drivers.some(ex => ex.id === d.id)) return false;
      const fee = computeDriverMarketValue(d);
      // Aggressive teams will go deeper into budget for stars
      const budgetFloor = personality === "aggressive" ? AI_MIN_REMAINING * 0.5 : AI_MIN_REMAINING;
      return t.budget >= fee + budgetFloor;
    });

    if (candidates.length === 0) return t;

    // Score each candidate for this team's philosophy
    const scored = candidates.map(d => ({
      driver: d,
      score: aiDriverDesirability(d, t, seasonRank, totalTeams),
      fee: computeDriverMarketValue(d),
    }));

    if (needsDriver) {
      // MUST sign — pick the best available within budget
      scored.sort((a, b) => b.score - a.score);
      const pick = scored[0];
      if (pick) {
        t.budget = Math.round((t.budget - pick.fee) * 10) / 10;
        t.drivers.push(stampDriverPurchase({
          ...pick.driver,
          currentSeasonPoints: 0,
          seasonPoints: 0,
        }, pick.fee));
        signedAgentIds.add(pick.driver.id);
        const pIdx = availablePool.findIndex(d => d.id === pick.driver.id);
        if (pIdx !== -1) availablePool.splice(pIdx, 1);

        const sigType = aiSigningType(pick.driver, t, seasonRank, totalTeams);
        const dAge = pick.driver.age || 26;
        const dRating = pick.driver.rating || 70;

        // Build a context-aware headline
        let sigIcon = "✍️";
        let sigColor = "#4fc3f7";
        if (sigType === "superstar") { sigIcon = "🌟"; sigColor = "#f4d03f"; }
        else if (sigType === "wonderkid") { sigIcon = "💫"; sigColor = "#00d25b"; }
        else if (sigType === "youngster") { sigIcon = "🌱"; sigColor = "#00d25b"; }
        else if (sigType === "star") { sigIcon = "⭐"; sigColor = "#fb8c00"; }
        else if (sigType === "desperation") { sigIcon = "🆘"; sigColor = "#e10600"; }
        else if (sigType === "development") { sigIcon = "📈"; sigColor = "#a78bfa"; }

        transfers.push({
          type: "signing",
          driver: pick.driver.name,
          driverRating: dRating,
          driverAge: dAge,
          driverTier: pick.driver.tier || "Average",
          driverNationality: pick.driver.nationality || "",
          fromTeam: null,
          toTeam: t.name,
          teamEmoji,
          teamPersonality: personality,
          fee: pick.fee,
          signingType: sigType,
          icon: sigIcon,
          color: sigColor,
        });
        totalChanges++;
      }
    }

    return t;
  });

  // Restore original team order
  const reordered = teams.map(orig => updatedTeams.find(u => u.id === orig.id) || orig);
  return { updatedTeams: reordered, transfers, releasedDrivers };
}

// ─────────────────────────────────────────────────────────────────────────────

// ─── GUARANTEE FULL ROSTERS ───────────────────────────────────────────────────
// FIXED: All auto-assigned drivers deduct correct market value from budget.
// Teams may never go below 0 budget (emergency auto-sign only if already negative).
// Duplicate driver prevention via usedDriverIds set.
// Transfer news generated for all auto-signings.
function fillMissingRosters(teams, allDrivers, allConstructors, allTracks) {
  const usedDriverIds = new Set(teams.flatMap(t => (t.drivers||[]).map(d => d.id)));
  const usedConsIds = new Set(teams.map(t => t.constructor?.id).filter(Boolean));
  const usedTrackIds = new Set(teams.map(t => t.track?.id).filter(Boolean));

  // Sort free pools: cheapest-first for drivers (so budget-limited teams can always afford something)
  const freeDrivers = [...allDrivers].filter(d => !usedDriverIds.has(d.id))
    .sort((a,b) => (a.basePrice||0) - (b.basePrice||0));
  const freeCons = [...allConstructors].filter(c => !usedConsIds.has(c.id))
    .sort((a,b) => a.basePrice - b.basePrice);
  const freeTracks = [...allTracks].filter(t => !usedTrackIds.has(t.id))
    .sort((a,b) => a.basePrice - b.basePrice);

  // Collect auto-signing news items

  const filledTeams = teams.map(t => {
    const team = { ...t, drivers:[...(t.drivers||[])], purchasePrices:{...(t.purchasePrices||{})} };

    // ── Fill drivers up to MAX_DRIVERS_PER_TEAM (minimum for racing), never exceed it ──
    // ROSTER LIMIT: teams may already have drivers from retention; only fill gaps.
    while (team.drivers.length < MAX_DRIVERS_PER_TEAM) {
      // Double-check no duplicate drivers
      const existingIds = new Set(team.drivers.map(d => d.id));

      // Find the cheapest free driver that team can afford and isn't already on the team
      const affordable = freeDrivers.find(d =>
        !existingIds.has(d.id) &&
        !usedDriverIds.has(d.id) &&
        (d.basePrice || Math.round((d.rating || 70) * 0.5)) <= Math.max(team.budget, 5)
      );

      if (affordable) {
        const idx = freeDrivers.indexOf(affordable);
        freeDrivers.splice(idx, 1);
        const cost = affordable.basePrice || Math.round((affordable.rating || 70) * 0.5);
        // Only deduct if team has budget; never go below 0 for established drivers
        if (cost <= team.budget) {
          team.budget = Math.round((team.budget - cost) * 10) / 10;
        } else {
          // Minimum budget floor: 0 (no going negative for regular signings)
          team.budget = 0;
        }
        team.purchasePrices[affordable.id] = cost;
        // ── v40 FIX: Restore career stats from allDrivers pool ──────────────
        // allDrivers is the authoritative source for accumulated career stats
        // (kept in sync by runRace Fix 1). Using Math.max ensures the higher
        // value always wins — defensive against any edge-case ordering.
        const masterRecord = allDrivers.find(d => d.id === affordable.id);
        const driverToAdd = masterRecord ? {
          ...affordable,
          wins:          Math.max(affordable.wins        || 0, masterRecord.wins        || 0),
          podiums:       Math.max(affordable.podiums     || 0, masterRecord.podiums     || 0),
          top10:         Math.max(affordable.top10       || 0, masterRecord.top10       || 0),
          totalPoints:   Math.max(affordable.totalPoints || 0, masterRecord.totalPoints || 0),
          championships: Math.max(affordable.championships || 0, masterRecord.championships || 0),
        } : { ...affordable };
        driverToAdd.baseAuctionPrice = affordable.basePrice;
        // ISSUE-04 FIX: driver may be re-entering a roster after release; ensure
        // the new season starts with zero season points.
        driverToAdd.currentSeasonPoints = 0;
        driverToAdd.seasonPoints = 0;
        team.drivers.push(stampDriverPurchase(driverToAdd, cost));
        usedDriverIds.add(affordable.id);
        // CAREER STATS: record every driver assigned to the player team,
        // including auto-fills, so Drivers Signed tracks the full career.
        if (!team.isAI) {
          const prevIds = team.careerDriverIds || [];
          if (!prevIds.includes(affordable.id)) {
            team.careerDriverIds = [...prevIds, affordable.id];
          }
        }
      } else {
        // Cannot afford any established driver — generate a low-rated driver
        const driverSeed = Date.now() + (team.id || '').charCodeAt(0) * 71 + team.drivers.length * 13 + Math.random() * 1000;
        const newDriver = generatePoolDriver(Math.floor(driverSeed));
        // Ensure driver ID is unique
        newDriver.id = `auto_${Date.now()}_${Math.random().toString(36).substr(2,5)}`;
        const driverCost = Math.max(4, newDriver.basePrice || 4);
        // Deduct if possible, but never go below 0 from an already-positive budget
        if (team.budget >= driverCost) {
          team.budget = Math.round((team.budget - driverCost) * 10) / 10;
        } else if (team.budget > 0) {
          // Partial payment — budget goes to 0
          team.budget = 0;
        }
        // If budget is already 0 or negative, emergency driver joins for free (minimum wage clause)
        team.purchasePrices[newDriver.id] = driverCost;
        newDriver.baseAuctionPrice = newDriver.basePrice;
        newDriver.currentSeasonPoints = 0;
        newDriver.seasonPoints = 0;
        team.drivers.push(stampDriverPurchase(newDriver, driverCost));
        usedDriverIds.add(newDriver.id);
        // CAREER STATS: emergency signings also count as drivers signed.
        if (!team.isAI) {
          const prevIds = team.careerDriverIds || [];
          if (!prevIds.includes(newDriver.id)) {
            team.careerDriverIds = [...prevIds, newDriver.id];
          }
        }
      }
    }

    // ── Fill constructor ─────────────────────────────────────────────────────
    if (!team.constructor && freeCons.length > 0) {
      const cheapCons = freeCons.find(c => c.basePrice <= Math.max(team.budget, 5)) || freeCons[0];
      const consIdx = freeCons.indexOf(cheapCons);
      freeCons.splice(consIdx, 1);
      team.constructor = cheapCons;
      usedConsIds.add(team.constructor.id);
      const cost = team.constructor.basePrice || 20;
      // AUCTION DEBT: deduct the full base price even if it causes a negative
      // balance. This happens only when the constructor would otherwise be
      // awarded for free (every remaining team lacked enough budget to bid).
      // Debt = basePrice − availablePurse; the negative balance persists and
      // is repaid automatically by future income (prize money, bonuses, grants).
      team.budget = Math.round((team.budget - cost) * 10) / 10;
      team.purchasePrices[team.constructor.id] = cost;
      // CAREER STATS: track every constructor ever auto-assigned to the player.
      if (!team.isAI) {
        const prevIds = team.careerConstructorIds || [];
        if (!prevIds.includes(team.constructor.id)) {
          team.careerConstructorIds = [...prevIds, team.constructor.id];
        }
      }
    }

    // ── Fill track ───────────────────────────────────────────────────────────
    if (!team.track && freeTracks.length > 0) {
      const cheapTrack = freeTracks.find(t => t.basePrice <= Math.max(team.budget, 5)) || freeTracks[0];
      const trackIdx = freeTracks.indexOf(cheapTrack);
      freeTracks.splice(trackIdx, 1);
      team.track = cheapTrack;
      usedTrackIds.add(team.track.id);
      team.powerUpsRemaining = (team.powerUpsRemaining||0) + team.track.powerUps;
      const cost = team.track.basePrice || 20;
      // AUCTION DEBT: same rule as constructor — deduct the full base price
      // even if it creates a negative balance, rather than giving the track
      // for free. Debt is repaid by subsequent income.
      team.budget = Math.round((team.budget - cost) * 10) / 10;
      team.purchasePrices[team.track.id] = cost;
      // CAREER STATS: track every circuit ever auto-assigned to the player.
      if (!team.isAI) {
        const prevIds = team.careerTrackIds || [];
        if (!prevIds.includes(team.track.id)) {
          team.careerTrackIds = [...prevIds, team.track.id];
        }
      }
    }

    // NOTE: budget may be negative here if auction debt was incurred (the team
    // received a constructor or track for which it lacked sufficient funds).
    // Do NOT clamp to 0 — the negative balance is intentional Auction Debt and
    // must persist so it can be repaid by future income (race prizes, bonuses).

    return team;
  });

  return { filledTeams };
}

// ─── ROSTER VALIDATION & DEDUP ───────────────────────────────────────────────
// Ensures every driver appears on exactly ONE team.
// Strategy: keep the LAST assignment found (latest team wins, mirrors transfer intent).
function validateAndDeduplicateRosters(teams) {
  // Pass 1 — find all duplicates
  const allDrivers = teams.flatMap(t => (t.drivers || []).map(d => ({ ...d, _teamId: t.id })));
  const seenIds = new Set();
  const seenNames = new Set();
  const duplicateIds = new Set();
  allDrivers.forEach(d => {
    if (seenIds.has(d.id))   duplicateIds.add(d.id);
    if (seenNames.has(d.name)) duplicateIds.add(d.id); // also catch name duplicates
    seenIds.add(d.id);
    seenNames.add(d.name);
  });

  if (duplicateIds.size === 0) return teams; // nothing to fix

  // Log the issue
  console.error(`[ROSTER VALIDATION] Duplicate driver(s) detected: ${[...duplicateIds].join(', ')}`);
  allDrivers
    .filter(d => duplicateIds.has(d.id))
    .forEach(d => console.error(`  Driver "${d.name}" (${d.id}) found on team ${d._teamId}`));

  // Pass 2 — determine the canonical team for each duplicate driver.
  // Rule: the last team in the array that contains the driver is authoritative
  // (this reflects the most recent transfer action).
  const canonicalTeam = {}; // driverId → teamId
  teams.forEach(team => {
    (team.drivers || []).forEach(d => {
      if (duplicateIds.has(d.id)) canonicalTeam[d.id] = team.id;
    });
  });

  // Pass 3 — strip duplicate entries from all non-canonical teams
  const cleaned = teams.map(team => ({
    ...team,
    drivers: (team.drivers || []).filter(d => {
      if (!duplicateIds.has(d.id)) return true; // not a dup, keep it
      return canonicalTeam[d.id] === team.id;   // only keep on canonical team
    }),
  }));

  // Verify
  const postCheck = cleaned.flatMap(t => (t.drivers || []).map(d => d.id));
  const stillDups = postCheck.filter((id, i, a) => a.indexOf(id) !== i);
  if (stillDups.length > 0) {
    console.error(`[ROSTER VALIDATION] Could not resolve all duplicates: ${stillDups.join(', ')}`);
  } else {
    // All duplicates resolved
  }

  return cleaned;
}

// ─── CENTRAL ROSTER VALIDATION ───────────────────────────────────────────────
// Each team holds exactly 0–MAX_DRIVERS_PER_TEAM senior drivers.
function validateTeamRoster(team) {
  const seniorCount = (team.drivers || []).length;
  const valid = seniorCount <= MAX_DRIVERS_PER_TEAM;
  return { valid, seniorCount, total: seniorCount };
}

// Returns true if the team can accept one more senior driver.
function canAddSeniorDriver(team) {
  return (team.drivers || []).length < MAX_DRIVERS_PER_TEAM;
}

// ─── ENFORCE ROSTER LIMITS (save-load cleanup + runtime safety) ───────────────
// Trims teams back to MAX_DRIVERS_PER_TEAM senior drivers.
// Released drivers are returned so callers can restore them to the global pool.
function enforceRosterLimits(teams) {
  let releasedCount = 0;
  const releasedDrivers = [];
  const cleanedTeams = teams.map(team => {
    let drivers = [...(team.drivers || [])];
    if (drivers.length > MAX_DRIVERS_PER_TEAM) {
      drivers.sort((a, b) => (b.rating || 70) - (a.rating || 70));
      const released = drivers.slice(MAX_DRIVERS_PER_TEAM);
      releasedCount += released.length;
      released.forEach(d => releasedDrivers.push({ ...d, _releasedFrom: team.id }));
      drivers = drivers.slice(0, MAX_DRIVERS_PER_TEAM);
      return { ...team, drivers };
    }
    return team;
  });
  if (releasedCount > 0) {
    console.warn(`[ROSTER LIMIT] Total drivers released to free agency: ${releasedCount}`);
  }
  return { cleanedTeams, releasedCount, releasedDrivers };
}

// ─── DRIVER ACCOUNTING VALIDATION ────────────────────────────────────────────
// ISSUE 2 FIX: Verifies that no driver has disappeared.
// Total Drivers = Drivers on Teams + Free Agents + Auction Pool (if in auction)
// Logs warnings if the counts are inconsistent. Call after any major state change.
function validateDriverAccounting(teams, globalPool, label) {
  const onTeams  = teams.flatMap(t => (t.drivers || []).map(d => d.id));
  const poolIds  = (globalPool || []).map(d => d.id);

  // Drivers on teams that are NOT in the global pool — indicates pool desync
  const missingFromPool = onTeams.filter(id => !poolIds.includes(id));
  const totalOnTeams    = onTeams.length;
  const totalPool       = poolIds.length;

  // Duplicate check
  const onTeamsDups = onTeams.filter((id, i, a) => a.indexOf(id) !== i);

  const valid = onTeamsDups.length === 0;
  if (!valid) {
    console.error(`[DRIVER ACCOUNTING][${label}] ✗ Duplicate driver IDs on teams: ${onTeamsDups.join(', ')}`);
  }
  if (missingFromPool.length > 0) {
    console.warn(`[DRIVER ACCOUNTING][${label}] ⚠ ${missingFromPool.length} roster drivers not in global pool — pool may be stale`);
  }

  // Roster limit check
  teams.forEach(t => {
    const { valid: rv, seniorCount } = validateTeamRoster(t);
    if (!rv) {
      console.error(`[DRIVER ACCOUNTING][${label}] ✗ ${t.name}: ${seniorCount} senior drivers EXCEEDS limits`);
    }
  });

  const freeAgentCount = poolIds.filter(id => !onTeams.includes(id)).length;
  console.log(`[DRIVER ACCOUNTING][${label}] Teams:${totalOnTeams} | Pool:${totalPool} | FreeAgents:${freeAgentCount} | Dups:${onTeamsDups.length}`);
  return valid;
}

// ─── SCREEN HISTORY & LOCK SETS ──────────────────────────────────────────────
const LOCKED_SCREENS = new Set(["auction","preRace","raceResult","endGame","auctionValidation"]);

// ─── CONFIRM DIALOG ──────────────────────────────────────────────────────────
function ConfirmDialog({ dialog, onCancel }) {
  if (!dialog) return null;
  const isAuctionExit = dialog.type === "auction-exit";
  return (
    <div style={{ position:"fixed", inset:0, zIndex:3000, display:"flex", alignItems:"center", justifyContent:"center", background:"rgba(0,0,0,0.75)", backdropFilter:"blur(6px)", animation:"fadeIn 0.15s ease" }}>
      <div style={{ background:"linear-gradient(145deg,rgba(18,14,26,0.98),rgba(12,10,20,0.98))", border:"1px solid rgba(225,6,0,0.35)", borderRadius:20, padding:"36px 40px", maxWidth:420, width:"90%", boxShadow:"0 0 60px rgba(225,6,0,0.18),0 24px 64px rgba(0,0,0,0.6)", animation:"scaleIn 0.2s cubic-bezier(0.34,1.56,0.64,1)", fontFamily:"'Rajdhani',sans-serif" }}>
        <div style={{ fontSize:11, color:"#e10600", letterSpacing:4, fontWeight:700, marginBottom:10 }}>CONFIRM ACTION</div>
        <div style={{ fontFamily:"'Orbitron',sans-serif", fontSize:22, fontWeight:700, color:"#fff", marginBottom:14 }}>{dialog.title}</div>
        <div style={{ fontSize:14, color:"rgba(255,255,255,0.55)", lineHeight:1.6, marginBottom:28 }}>{dialog.body}</div>
        {isAuctionExit ? (
          <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
            <button onClick={dialog.onSaveAndExit} style={{ width:"100%", background:"linear-gradient(135deg,#00d25b,#10b981)", border:"none", borderRadius:10, padding:"14px 0", color:"#fff", fontFamily:"'Rajdhani',sans-serif", fontSize:14, fontWeight:700, letterSpacing:1.5, textTransform:"uppercase", cursor:"pointer", boxShadow:"0 4px 16px rgba(0,210,91,0.3)", transition:"all 0.2s" }}
              onMouseEnter={e=>{ e.currentTarget.style.filter="brightness(1.1)"; e.currentTarget.style.transform="translateY(-1px)"; }}
              onMouseLeave={e=>{ e.currentTarget.style.filter="none"; e.currentTarget.style.transform="translateY(0)"; }}
            >
              💾 Save and Exit
            </button>
            <button onClick={dialog.onConfirm} style={{ width:"100%", background:"linear-gradient(135deg,#fb8c00,#e67e00)", border:"none", borderRadius:10, padding:"12px 0", color:"#fff", fontFamily:"'Rajdhani',sans-serif", fontSize:13, fontWeight:700, letterSpacing:1.5, textTransform:"uppercase", cursor:"pointer", boxShadow:"0 4px 12px rgba(251,140,0,0.25)", transition:"all 0.2s" }}
              onMouseEnter={e=>{ e.currentTarget.style.filter="brightness(1.1)"; e.currentTarget.style.transform="translateY(-1px)"; }}
              onMouseLeave={e=>{ e.currentTarget.style.filter="none"; e.currentTarget.style.transform="translateY(0)"; }}
            >
              Exit Without Saving
            </button>
            <button onClick={onCancel} className="btn-secondary" style={{ width:"100%", fontSize:13, background:"rgba(255,255,255,0.04)", border:"1px solid rgba(255,255,255,0.1)" }}>Cancel</button>
          </div>
        ) : (
          <div style={{ display:"flex", gap:12 }}>
            <button onClick={onCancel} className="btn-secondary" style={{ flex:1, fontSize:14 }}>Cancel</button>
            <button onClick={dialog.onConfirm} style={{ flex:1, background:"linear-gradient(135deg,#e10600,#b00400)", border:"none", borderRadius:10, padding:"13px 0", color:"#fff", fontFamily:"'Rajdhani',sans-serif", fontSize:14, fontWeight:700, letterSpacing:1.5, textTransform:"uppercase", cursor:"pointer", boxShadow:"0 4px 16px rgba(225,6,0,0.3)", transition:"all 0.2s" }}
              onMouseEnter={e=>{ e.currentTarget.style.filter="brightness(1.1)"; e.currentTarget.style.transform="translateY(-1px)"; }}
              onMouseLeave={e=>{ e.currentTarget.style.filter="none"; e.currentTarget.style.transform="translateY(0)"; }}
            >
              Confirm
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

