// ─── YOUR CAREER LEGACY (career finale — final screen before Main Menu) ────
function CareerLegacyScreen({ gameState, hofData, budgetWatermark, onMainMenu }) {
  const [showConfetti, setShowConfetti] = useState(false);
  const [revealed, setRevealed] = useState(false);
  useEffect(() => {
    const t1 = setTimeout(() => setShowConfetti(true), 300);
    const t2 = setTimeout(() => setRevealed(true), 200);
    return () => { clearTimeout(t1); clearTimeout(t2); };
  }, []);

  const player = gameState?.teams?.find(t => !t.isAI);
  const seasonsPlayed = TOTAL_SEASONS;
  const driverChampionships = (gameState?.seasonChampions || []).filter(s => s.champion?.id === player?.id).length;
  const constructorChampionships = player?.seasonsWon || 0;
  const totalWins = player?.raceWins || 0;
  const totalPodiums = player?.podiums || 0;
  const totalPoints = player?.totalPoints || 0;
  // ── Career franchise statistics — read directly from the monotonically-growing
  // career arrays. These are written at every acquisition point (auction,
  // auto-fill) so they never decrease and never depend on who is still alive
  // in the driver pool or currently on the roster.
  //
  // Fallback for saves predating this field: derive from purchasePrices ∩ pool
  // (old behaviour) so existing saves don't show 0.
  const driverIdSet      = new Set((gameState?.drivers || []).map(d => d.id));
  const constructorIdSet = new Set((gameState?.constructors || []).map(c => c.id));
  const trackIdSet       = new Set((gameState?.tracks || []).map(t => t.id));

  const driversSignedCount = player?.careerDriverIds?.length
    ? player.careerDriverIds.length
    : (() => {
        // Legacy fallback: purchasePrices ∩ pool + current roster
        const currentRosterIds = (player?.drivers || []).map(d => d.id);
        const ids = new Set([
          ...Object.keys(player?.purchasePrices || {}).filter(id => driverIdSet.has(id)),
          ...currentRosterIds,
        ]);
        return ids.size;
      })();

  const constructorsOwned = player?.careerConstructorIds?.length
    ? player.careerConstructorIds.length
    : (() => {
        // Legacy fallback
        const ids = Object.keys(player?.purchasePrices || {}).filter(id => constructorIdSet.has(id));
        return ids.length || (player?.constructor ? 1 : 0);
      })();

  const tracksOwned = player?.careerTrackIds?.length
    ? player.careerTrackIds.length
    : (() => {
        // Legacy fallback
        const ids = Object.keys(player?.purchasePrices || {}).filter(id => trackIdSet.has(id));
        return ids.length || (player?.track ? 1 : 0);
      })();
  const powerUpsUsed = player?.powerUpsUsed || 0;
  const totalEarnings = player?.totalEarnings || 0;
  const finalBudget = player?.budget || 0;
  const finalTeamValue = (player?.totalEarnings || 0) + (player?.raceWins || 0) * 2 + (constructorChampionships * 50);
  const highestBudget = Math.max(budgetWatermark?.max ?? finalBudget, finalBudget);
  const lowestBudget = Math.min(budgetWatermark?.min ?? finalBudget, finalBudget);

  const goatScore = calculateGoatScore({ championships:constructorChampionships, wins:totalWins, podiums:totalPodiums, points:totalPoints });
  const rank = getManagerRank(goatScore);

  // Season Journey Timeline — sourced from hofData.playerCareer.timeline, the
  // same persisted per-season {season, rank, champion, runnerUp} record already
  // written by checkUnlockConditions/saveHOF after every season and already
  // rendered on TrophyRoomScreen. No new tracking or calculation introduced.
  const pc = hofData?.playerCareer || {};
  const timeline = pc.timeline || [];
  const rankLabel = (r) => {
    if (r === 1) return "🏆 Champion";
    if (r === 2) return "🥈 Runner-Up";
    if (r === 3) return "🥉 3rd Place";
    return `P${r}`;
  };

  const statGroups = [
    { title:"CAREER", stats:[
      { l:"Seasons Played", v:seasonsPlayed, icon:"📅" },
      { l:"Driver Championships", v:driverChampionships, icon:"🥇" },
      { l:"Constructor Championships", v:constructorChampionships, icon:"🏆" },
      { l:"Race Wins", v:totalWins, icon:"🏁" },
      { l:"Podiums", v:totalPodiums, icon:"🎖" },
      { l:"Career Points", v:totalPoints, icon:"📊" },
    ]},
    { title:"FRANCHISE", stats:[
      { l:"Drivers Signed", v:driversSignedCount, icon:"🤝" },
      { l:"Constructors Owned", v:constructorsOwned, icon:"🏎" },
      { l:"Tracks Owned", v:tracksOwned, icon:"🗺" },
      { l:"Power-Ups Used", v:powerUpsUsed, icon:"⚡" },
    ]},
    { title:"FINANCES", stats:[
      { l:"Total Earnings", v:`${totalEarnings.toFixed(1)}M`, icon:"💰" },
      { l:"Highest Budget", v:`${highestBudget.toFixed(1)}M`, icon:"📈" },
      { l:"Lowest Budget", v:`${lowestBudget.toFixed(1)}M`, icon:"📉" },
      { l:"Final Budget", v:`${finalBudget.toFixed(1)}M`, icon:"💵" },
      { l:"Final Team Value", v:`${finalTeamValue.toFixed(1)}M`, icon:"💎" },
    ]},
  ];

  return (
    <div style={{ minHeight:"100vh", background:"linear-gradient(135deg,#080810 0%,#0f0a14 50%,#0a0a14 100%)", fontFamily:"'Rajdhani',sans-serif", color:"#fff", padding:"48px 20px 60px", position:"relative", overflow:"hidden" }}>
      <style>{FINALE_CSS}</style>
      {showConfetti && <Confetti />}
      <div style={{ position:"fixed", inset:0, backgroundImage:"linear-gradient(rgba(244,208,63,0.025) 1px,transparent 1px),linear-gradient(90deg,rgba(244,208,63,0.025) 1px,transparent 1px)", backgroundSize:"70px 70px", pointerEvents:"none" }}/>
      <div style={{ position:"fixed", top:"3%", left:"50%", transform:"translateX(-50%)", width:900, height:480, background:`radial-gradient(ellipse,${rank.glow} 0%,transparent 70%)`, pointerEvents:"none" }}/>

      <div style={{ maxWidth:680, margin:"0 auto", position:"relative", zIndex:1 }}>
        <div style={{ textAlign:"center", marginBottom:30, animation:"finaleHeaderIn 0.6s ease" }}>
          <div style={{ fontSize:11, letterSpacing:8, color:"#f4d03f", fontWeight:700, marginBottom:10 }}>FOUR SEASONS · CAREER COMPLETE</div>
          <div style={{ fontFamily:"'Orbitron',sans-serif", fontSize:"clamp(28px,6vw,46px)", fontWeight:900, lineHeight:1.05, background:"linear-gradient(135deg,#f4d03f,#fff5b0,#f4d03f)", backgroundSize:"200% auto", WebkitBackgroundClip:"text", WebkitTextFillColor:"transparent", animation:"finaleShimmer 3s linear infinite" }}>
            🏆 YOUR CAREER LEGACY
          </div>
          {player && <div style={{ fontSize:14, color:"rgba(255,255,255,0.45)", marginTop:10, letterSpacing:1 }}>{player.playerName || "Manager"} · {player.name}</div>}
        </div>

        {/* Manager Trophy + Rank — the hero element of this screen */}
        <div style={{
          textAlign:"center",
          background:`linear-gradient(160deg,${rank.glow},transparent 70%)`, border:`2px solid ${rank.color}66`,
          borderRadius:28, padding:"44px 28px 36px", marginBottom:32, position:"relative", overflow:"hidden",
          opacity:revealed?1:0, transform:revealed?"scale(1)":"scale(0.92)", transition:"all 0.6s cubic-bezier(0.22,1,0.36,1)",
          boxShadow:`0 0 90px ${rank.glow}, 0 24px 60px rgba(0,0,0,0.45)`,
        }}>
          <div style={{ position:"absolute", inset:0, background:`radial-gradient(ellipse at 50% 0%,${rank.glow},transparent 70%)`, pointerEvents:"none", animation:"finaleSpotlight 3s ease infinite" }}/>
          <div style={{ position:"relative", zIndex:1 }}>
            <div style={{ fontSize:"clamp(80px,16vw,128px)", lineHeight:1, filter:`drop-shadow(0 0 40px ${rank.glow})`, animation:"finaleTrophyShine 2.2s ease infinite, finaleTrophyBounce 2.6s ease infinite", display:"inline-block" }}>🏆</div>
            <div style={{ fontSize:10, letterSpacing:5, color:"rgba(255,255,255,0.5)", fontWeight:700, marginTop:14, marginBottom:8 }}>MANAGER RANK</div>
            <div style={{ fontFamily:"'Orbitron',sans-serif", fontSize:"clamp(26px,6vw,44px)", fontWeight:900, color:rank.color, letterSpacing:1, animation:"finaleGoldPulse 2.4s ease infinite" }}>
              {rank.label}
            </div>
            <div style={{ fontSize:14, color:"rgba(255,255,255,0.45)", marginTop:12 }}>Legacy Score: <span style={{ fontFamily:"'Orbitron',sans-serif", color:rank.color, fontWeight:700 }}>{goatScore.toLocaleString()}</span></div>
          </div>
        </div>

        {/* Season Journey Timeline */}
        <div style={{ background:"rgba(255,255,255,0.03)", border:"1px solid rgba(255,255,255,0.08)", borderRadius:20, padding:"22px 24px", marginBottom:28, animation:"finaleCardIn 0.6s ease 0.15s both" }}>
          <div style={{ fontSize:10, letterSpacing:4, color:"rgba(255,255,255,0.4)", fontWeight:700, marginBottom:18 }}>SEASON JOURNEY</div>
          {timeline.length === 0 && (
            <div style={{ textAlign:"center", padding:"12px 0", color:"rgba(255,255,255,0.25)", fontSize:13 }}>No season-by-season record was found for this career.</div>
          )}
          {timeline.length > 0 && (
            <div style={{ position:"relative", paddingLeft:24 }}>
              <div style={{ position:"absolute", left:6, top:8, bottom:8, width:2, background:"linear-gradient(180deg,#f4d03f,rgba(244,208,63,0.15))" }}/>
              {timeline.map((t, i) => (
                <div key={i} style={{ display:"flex", alignItems:"flex-start", gap:16, marginBottom:i===timeline.length-1?0:14, animation:`finaleTimelineSlide 0.35s ease ${i*0.1}s both`, position:"relative" }}>
                  <div style={{ position:"absolute", left:-18, top:4, width:14, height:14, borderRadius:"50%", background:t.champion?"#f4d03f":t.runnerUp?"#c0c0c0":"rgba(255,255,255,0.15)", border:`2px solid ${t.champion?"#f4d03f88":t.runnerUp?"#c0c0c088":"rgba(255,255,255,0.1)"}`, flexShrink:0 }}/>
                  <div style={{ flex:1, display:"flex", justifyContent:"space-between", alignItems:"center", flexWrap:"wrap", gap:6 }}>
                    <div style={{ fontSize:14, fontWeight:700, color:t.champion?"#f4d03f":t.runnerUp?"#c0c0c0":"#fff" }}>Season {t.season} → {rankLabel(t.rank)}</div>
                    <div style={{ fontFamily:"'Orbitron',sans-serif", fontSize:13, fontWeight:700, color:"rgba(255,255,255,0.5)" }}>{t.points}pts</div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Stat cards — grouped, not a plain table */}
        {statGroups.map((group, gi) => (
          <div key={group.title} style={{ marginBottom:24, animation:`finaleCardIn 0.6s ease ${0.2 + gi*0.1}s both` }}>
            <div style={{ fontSize:10, letterSpacing:4, color:"rgba(255,255,255,0.35)", fontWeight:700, marginBottom:12, paddingLeft:4 }}>{group.title}</div>
            <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(140px,1fr))", gap:10 }}>
              {group.stats.map(({ l, v, icon }) => (
                <div key={l} style={{ background:"rgba(255,255,255,0.04)", border:"1px solid rgba(255,255,255,0.08)", borderRadius:14, padding:"16px 14px", textAlign:"center" }}>
                  <div style={{ fontSize:20, marginBottom:6 }}>{icon}</div>
                  <div style={{ fontFamily:"'Orbitron',sans-serif", fontSize:18, fontWeight:900, color:"#fff" }}>{v}</div>
                  <div style={{ fontSize:10, color:"rgba(255,255,255,0.4)", letterSpacing:0.5, marginTop:4 }}>{l}</div>
                </div>
              ))}
            </div>
          </div>
        ))}

        <div style={{ textAlign:"center", marginTop:8, animation:"fadeIn 0.5s ease 0.6s both" }}>
          <button onClick={onMainMenu} style={{ background:"linear-gradient(135deg,#e10600,#c00400)", border:"none", borderRadius:12, padding:"16px 56px", color:"#fff", fontFamily:"'Rajdhani',sans-serif", fontSize:16, fontWeight:800, letterSpacing:3, textTransform:"uppercase", cursor:"pointer", boxShadow:"0 6px 24px rgba(225,6,0,0.4)" }}>
            🏁 Main Menu
          </button>
        </div>
      </div>
    </div>
  );
}

// ─── END GAME ─────────────────────────────────────────────────────────────────
function EndGameScreen({ gameState, onRestart, onRestartCareer, onHallOfFame, onTrophyRoom }) {
  const { teams, seasonChampions, allRaceResults } = gameState;
  const [tab, setTab] = useState("overview");
  const [revealed, setRevealed] = useState(0);
  const [showConfetti, setShowConfetti] = useState(false);

  useEffect(() => {
    const t = setInterval(() => setRevealed(r => r < 10 ? r+1 : (clearInterval(t), 10)), 150);
    setTimeout(() => setShowConfetti(true), 800);
    return () => clearInterval(t);
  }, []);

  const overallStandings = useMemo(() => [...teams].sort((a,b) => {
    // Use calculateGoatScore — single source of truth for all GOAT/dynasty rankings.
    // Team objects use seasonsWon (not championships) and raceWins (not wins), so map them.
    const wA = a.seasonsWon || seasonChampions?.filter(s=>s.champion?.id===a.id).length || 0;
    const wB = b.seasonsWon || seasonChampions?.filter(s=>s.champion?.id===b.id).length || 0;
    const goatA = calculateGoatScore({ championships:wA, wins:a.raceWins||0, podiums:a.podiums||0, points:a.totalPoints||0 });
    const goatB = calculateGoatScore({ championships:wB, wins:b.raceWins||0, podiums:b.podiums||0, points:b.totalPoints||0 });
    return goatB - goatA;
  }), [teams, seasonChampions]);
  const wealthStandings = useMemo(() => [...teams].sort((a,b) => (b.totalEarnings||0)-(a.totalEarnings||0)), [teams]);
  const player = teams?.find(t=>!t.isAI);
  const playerRank = overallStandings.findIndex(t=>!t.isAI)+1;
  const season1Champ = seasonChampions?.find(s=>s.season===1)?.champion;
  const lastSeason = TOTAL_SEASONS;
  const lastSeasonChamp = seasonChampions?.find(s=>s.season===lastSeason)?.champion || seasonChampions?.slice(-1)[0]?.champion;
  const overallChamp = overallStandings[0];
  const richestTeam = wealthStandings[0];
  const mostWins = useMemo(() => [...teams].sort((a,b)=>(b.raceWins||0)-(a.raceWins||0))[0], [teams]);
  const driverList = useMemo(() => {
    const driverStats = {};
    (allRaceResults||[]).forEach(({ results }) => {
      (results||[]).forEach(r => {
        if (!driverStats[r.driverId]) driverStats[r.driverId] = { name:r.driverName, races:0, points:0, wins:0, podiums:0, top10:0 };
        driverStats[r.driverId].races++;
        driverStats[r.driverId].points += r.points;
        if (r.position===1) driverStats[r.driverId].wins++;
        if (r.position<=3) driverStats[r.driverId].podiums++;
        if (r.position<=10) driverStats[r.driverId].top10++;
      });
    });
    return Object.values(driverStats).sort((a,b)=>b.points-a.points).slice(0,10);
  }, [allRaceResults]);
  const mostSuccessfulDriver = driverList[0];
  const mostPodiums = useMemo(() => [...driverList].sort((a,b)=>b.podiums-a.podiums)[0], [driverList]);
  const allUpgrades = useMemo(() => teams.flatMap(t => (t.upgradeHistory||[]).map(u=>({...u,teamName:t.name}))), [teams]);
  const playerFlair = playerRank===1?"🏆 FRANCHISE CHAMPION":playerRank<=3?"🥉 PODIUM FINISHER":playerRank<=5?"💪 STRONG CONTENDER":"📈 MID-FIELD RUNNER";

  return (
    <div style={{ minHeight:"100vh", background:"linear-gradient(180deg,#08080f 0%,#100810 50%,#080f10 100%)", fontFamily:"'Rajdhani',sans-serif", color:"#fff", padding:24, position:"relative", overflow:"hidden" }}>
      {showConfetti && <Confetti />}
      <div style={{ position:"fixed", inset:0, backgroundImage:"linear-gradient(rgba(244,208,63,0.02) 1px,transparent 1px),linear-gradient(90deg,rgba(244,208,63,0.02) 1px,transparent 1px)", backgroundSize:"80px 80px", pointerEvents:"none" }}/>
      <div style={{ position:"fixed", top:"10%", left:"50%", transform:"translateX(-50%)", width:800, height:400, background:"radial-gradient(ellipse,rgba(244,208,63,0.05) 0%,transparent 70%)", pointerEvents:"none" }}/>
      <div style={{ maxWidth:1040, margin:"0 auto", position:"relative" }}>
        <div style={{ textAlign:"center", marginBottom:48, animation:"fadeIn 0.8s ease" }}>
          <div style={{ fontSize:11, letterSpacing:8, color:"#f4d03f", fontWeight:700, marginBottom:16 }}>FOUR SEASONS COMPLETE · CAREER OVER</div>
          <div style={{ fontFamily:"'Orbitron',sans-serif", fontSize:72, fontWeight:900, lineHeight:0.9, marginBottom:8, background:"linear-gradient(135deg,#f4d03f,#d4ac0d,#f4d03f)", backgroundSize:"200% auto", WebkitBackgroundClip:"text", WebkitTextFillColor:"transparent", animation:"shimmerGold 3s linear infinite" }}>HALL OF<br/>FAME</div>
          <div style={{ fontSize:14, color:"rgba(255,255,255,0.35)", letterSpacing:3 }}>{GAME_TITLE_UPPER} V{GAME_VERSION} · CAREER COMPLETE</div>
        </div>
        {/* Champion podium */}
        <div style={{ display:"grid", gridTemplateColumns:"1fr 1.15fr 1fr", gap:16, marginBottom:28 }}>
          {[
            { label:"Season 1 Champion", team:season1Champ, color:"#c0c0c0", icon:"🥈", delay:0.2 },
            { label:"Overall Champion",  team:overallChamp,  color:"#f4d03f", icon:"🏆", delay:0, big:true },
            { label:`Season ${lastSeason} Champion`, team:lastSeasonChamp, color:"#cd7f32", icon:"🥉", delay:0.4 }
          ].map(({ label, team, color, icon, delay, big }) => (
            <div key={label} style={{ background:`linear-gradient(135deg,${color}12,${color}04)`, border:`1px solid ${color}44`, borderRadius:20, padding:big?32:24, textAlign:"center", animation:`slideUp 0.6s ease ${delay}s both`, position:"relative", overflow:"hidden" }}>
              {big && <div style={{ position:"absolute", inset:0, background:`radial-gradient(circle at center,${color}10,transparent)`, pointerEvents:"none" }}/>}
              <div style={{ fontSize:big?56:40, marginBottom:10, animation:`trophy 0.8s ease ${delay+0.3}s both`, display:"inline-block" }}>{icon}</div>
              <div style={{ fontSize:10, color:"rgba(255,255,255,0.4)", letterSpacing:4, marginBottom:8 }}>{label}</div>
              <div style={{ fontFamily:"'Orbitron',sans-serif", fontSize:big?22:17, fontWeight:700, color }}>{team?.name||"—"}</div>
              {/* All three cards show the same four stats — only sizing differs */}
              {team && (
                <div style={{ marginTop:10, display:"flex", gap:big?16:10, justifyContent:"center", flexWrap:"wrap", borderTop:"1px solid rgba(255,255,255,0.1)", paddingTop:10 }}>
                  {[
                    { l:"Championships", v:team.seasonsWon||0,    c:"#f4d03f" },
                    { l:"Wins",          v:team.raceWins||0,      c:"#fff" },
                    { l:"Podiums",       v:team.podiums||0,       c:"#c0c0c0" },
                    { l:"Points",        v:team.totalPoints||0,   c:"#4fc3f7" },
                  ].map(({ l, v, c }) => (
                    <div key={l} style={{ textAlign:"center", minWidth:big?54:40 }}>
                      <div style={{ fontFamily:"Orbitron", fontSize:big?17:13, fontWeight:900, color:c }}>{v}</div>
                      <div style={{ fontSize:big?9:8, color:"rgba(255,255,255,0.35)", letterSpacing:1, marginTop:2 }}>{l}</div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          ))}
        </div>
        {/* Record holders */}
        <div style={{ display:"grid", gridTemplateColumns:"repeat(4,1fr)", gap:12, marginBottom:24, animation:"slideUp 0.5s ease 0.5s both" }}>
          {[
            { icon:"💰", label:"Richest Team", val:richestTeam?.name, sub:`${(richestTeam?.totalEarnings||0).toFixed(1)}M earned` },
            { icon:"🏁", label:"Most Race Wins", val:mostWins?.name, sub:`${mostWins?.raceWins||0} wins` },
            { icon:"🌟", label:"Top Driver", val:mostSuccessfulDriver?.name, sub:`${mostSuccessfulDriver?.points||0} pts` },
            { icon:"🥉", label:"Most Podiums", val:mostPodiums?.name, sub:`${mostPodiums?.podiums||0} podiums` }
          ].map(({ icon, label, val, sub }) => (
            <div key={label} className="glass-card" style={{ padding:20, textAlign:"center" }}>
              <div style={{ fontSize:28, marginBottom:8 }}>{icon}</div>
              <div style={{ fontSize:10, color:"rgba(255,255,255,0.35)", letterSpacing:2, marginBottom:6 }}>{label}</div>
              <div style={{ fontSize:14, fontWeight:700, marginBottom:3 }}>{val||"—"}</div>
              <div style={{ fontSize:11, color:"rgba(255,255,255,0.35)" }}>{sub}</div>
            </div>
          ))}
        </div>
        {/* Player franchise report */}
        <div style={{ background:`linear-gradient(135deg,rgba(79,195,247,0.08),rgba(79,195,247,0.03))`, border:"1px solid rgba(79,195,247,0.25)", borderRadius:20, padding:28, marginBottom:28, animation:"slideUp 0.5s ease 0.6s both" }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:20 }}>
            <div>
              <div style={{ fontSize:10, color:"#4fc3f7", letterSpacing:4, marginBottom:6, fontWeight:700 }}>YOUR FRANCHISE REPORT</div>
              <div style={{ fontFamily:"Orbitron", fontSize:22, fontWeight:700 }}>{player?.name}</div>
            </div>
            <div style={{ textAlign:"right" }}>
              <div style={{ fontSize:10, color:"rgba(255,255,255,0.35)", marginBottom:4 }}>FINAL RANK</div>
              <div style={{ fontFamily:"Orbitron", fontSize:36, fontWeight:700, color:playerRank===1?"#f4d03f":playerRank<=3?"#c0c0c0":"rgba(255,255,255,0.5)" }}>P{playerRank}</div>
            </div>
          </div>
          <div style={{ display:"grid", gridTemplateColumns:"repeat(5,1fr)", gap:10, marginBottom:16 }}>
            {[
              { label:"Constructor Titles", val:player?.seasonsWon||0, c:"#f4d03f" },
              { label:"Career Points", val:player?.totalPoints||0, c:"#4fc3f7" },
              { label:"Race Wins", val:player?.raceWins||0, c:"#fff" },
              { label:"Podiums", val:player?.podiums||0, c:"#c0c0c0" },
              { label:"Total Earnings", val:`${(player?.totalEarnings||0).toFixed(1)}M`, c:"#00d25b" }
            ].map(({ label, val, c }) => (
              <div key={label} style={{ background:label==="Constructor Titles"?"rgba(244,208,63,0.1)":"rgba(255,255,255,0.05)", borderRadius:12, padding:"14px 12px", textAlign:"center", border:label==="Constructor Titles"?"1px solid rgba(244,208,63,0.3)":"none" }}>
                <div style={{ fontSize:10, color:"rgba(255,255,255,0.35)", letterSpacing:1, marginBottom:6 }}>{label}</div>
                <div style={{ fontFamily:"Orbitron", fontSize:20, fontWeight:700, color:c }}>{val}</div>
              </div>
            ))}
          </div>
          <div style={{ padding:"14px 20px", background:"rgba(255,255,255,0.04)", borderRadius:10, textAlign:"center" }}>
            <span style={{ fontFamily:"Orbitron", fontSize:16, fontWeight:700, color:playerRank===1?"#f4d03f":playerRank<=3?"#c0c0c0":"rgba(255,255,255,0.5)" }}>{playerFlair}</span>
          </div>
        </div>
        {/* Tabs */}
        <div style={{ display:"flex", gap:4, marginBottom:20, flexWrap:"wrap", animation:"fadeIn 0.4s ease 0.7s both" }}>
          {[["overview","Final Standings"],["drivers","Driver Stats"],["earnings","Earnings"],["upgrades","Upgrades"]].map(([key,label]) => (
            <button key={key} onClick={()=>setTab(key)}
              style={{ background:tab===key?"rgba(244,208,63,0.12)":"rgba(255,255,255,0.04)", border:`1px solid ${tab===key?"rgba(244,208,63,0.3)":"rgba(255,255,255,0.06)"}`, borderRadius:8, padding:"9px 18px", color:tab===key?"#f4d03f":"rgba(255,255,255,0.45)", fontFamily:"inherit", fontSize:13, fontWeight:700, cursor:"pointer", letterSpacing:1 }}>
              {label}
            </button>
          ))}
        </div>
        {tab === "overview" && (
          <div className="glass-card" style={{ padding:24 }}>
            <div style={{ fontSize:10, color:"rgba(255,255,255,0.35)", letterSpacing:3, marginBottom:16 }}>FINAL CHAMPIONSHIP STANDINGS</div>
            {overallStandings.map((t,i) => (
              <div key={t.id} className="standings-row" style={{ background:!t.isAI?"rgba(79,195,247,0.06)":i===0?"rgba(244,208,63,0.04)":"rgba(255,255,255,0.02)", border:!t.isAI?"1px solid rgba(79,195,247,0.15)":i===0?"1px solid rgba(244,208,63,0.15)":"1px solid transparent", animation:`slideIn 0.3s ease ${i*0.04}s both` }}>
                <div style={{ width:34, height:34, borderRadius:"50%", background:i===0?"rgba(244,208,63,0.2)":i===1?"rgba(255,255,255,0.08)":i===2?"rgba(205,127,50,0.2)":"rgba(255,255,255,0.04)", display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"Orbitron", fontSize:14, fontWeight:700, color:i===0?"#f4d03f":i===1?"rgba(255,255,255,0.6)":i===2?"#cd7f32":"rgba(255,255,255,0.25)" }}>{i+1}</div>
                <div style={{ width:8, height:8, borderRadius:"50%", background:getTeamColor(teams.indexOf(t)) }}/>
                <div style={{ flex:1 }}>
                  <div style={{ fontSize:15, fontWeight:700, color:t.isAI?"#fff":"#4fc3f7" }}>{!t.isAI?"★ ":""}{t.name}</div>
                  <div style={{ fontSize:11, color:"rgba(255,255,255,0.35)" }}>{(t.seasonPoints||[]).map((p,si)=>`S${si+1}:${p}pts`).join(" · ")} · Career Wins:{t.raceWins||0}</div>
                </div>
                <div style={{ display:"flex", alignItems:"center", gap:12 }}>
                  {(t.seasonsWon||0) > 0 && (
                    <div style={{ display:"flex", gap:3 }}>
                      {Array.from({length:t.seasonsWon||0}).map((_,ci) => (
                        <span key={ci} style={{ fontSize:16 }}>🏆</span>
                      ))}
                    </div>
                  )}
                  <div style={{ textAlign:"right" }}>
                    <div style={{ fontFamily:"Orbitron", fontSize:18, fontWeight:700 }}>{t.totalPoints||0} <span style={{ fontSize:11, color:"rgba(255,255,255,0.3)" }}>career pts</span></div>
                    <div style={{ fontSize:12, color:"#00d25b" }}>{(t.totalEarnings||0).toFixed(1)}M</div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
        {tab === "drivers" && (
          <div className="glass-card" style={{ padding:24 }}>
            <div style={{ fontSize:10, color:"rgba(255,255,255,0.35)", letterSpacing:3, marginBottom:16 }}>TOP DRIVER PERFORMANCES — ALL SEASONS</div>
            {driverList.map((d,i) => (
              <div key={d.name} className="standings-row" style={{ animation:`slideIn 0.3s ease ${i*0.04}s both` }}>
                <div style={{ width:28, fontFamily:"Orbitron", fontSize:12, fontWeight:700, color:"rgba(255,255,255,0.35)", textAlign:"center" }}>{i+1}</div>
                <div style={{ flex:1 }}>
                  <div style={{ fontSize:14, fontWeight:700 }}>{d.name}</div>
                  <div style={{ fontSize:11, color:"rgba(255,255,255,0.35)" }}>{d.races} races</div>
                </div>
                <div style={{ display:"flex", gap:20 }}>
                  {[{v:d.points,l:"pts",c:"#fff"},{v:d.wins,l:"wins",c:"#f4d03f"},{v:d.podiums,l:"pods",c:"#c0c0c0"},{v:d.top10,l:"top10",c:"#4fc3f7"}].map(({v,l,c})=>(
                    <div key={l} style={{ textAlign:"center", minWidth:36 }}>
                      <div style={{ fontFamily:"Orbitron", fontSize:16, fontWeight:700, color:c }}>{v}</div>
                      <div style={{ fontSize:10, color:"rgba(255,255,255,0.35)" }}>{l}</div>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}
        {tab === "earnings" && (
          <div className="glass-card" style={{ padding:24 }}>
            <div style={{ fontSize:10, color:"rgba(255,255,255,0.35)", letterSpacing:3, marginBottom:16 }}>FRANCHISE EARNINGS RANKING</div>
            {wealthStandings.map((t,i) => (
              <div key={t.id} className="standings-row" style={{ animation:`slideIn 0.3s ease ${i*0.04}s both` }}>
                <div style={{ width:28, fontFamily:"Orbitron", fontSize:13, fontWeight:700, color:"rgba(255,255,255,0.3)", textAlign:"center" }}>{i+1}</div>
                <div style={{ width:8, height:8, borderRadius:"50%", background:getTeamColor(teams.indexOf(t)) }}/>
                <div style={{ flex:1, fontSize:14, fontWeight:600, color:t.isAI?"#fff":"#4fc3f7" }}>{!t.isAI?"★ ":""}{t.name}</div>
                <div style={{ textAlign:"right" }}>
                  <div style={{ fontFamily:"Orbitron", fontSize:18, fontWeight:700, color:"#00d25b" }}>{(t.totalEarnings||0).toFixed(1)}M</div>
                  <div style={{ fontSize:11, color:"rgba(255,255,255,0.35)" }}>Budget: {(t.budget||0).toFixed(1)}M · PU: {t.powerUpsUsed||0}</div>
                </div>
              </div>
            ))}
          </div>
        )}
        {tab === "upgrades" && (
          <div className="glass-card" style={{ padding:24 }}>
            <div style={{ fontSize:10, color:"rgba(255,255,255,0.35)", letterSpacing:3, marginBottom:16 }}>UPGRADE HISTORY — ALL TEAMS</div>
            {allUpgrades.length === 0 && <div style={{ color:"rgba(255,255,255,0.3)", fontSize:13 }}>No upgrades were made this career.</div>}
            {allUpgrades.map((u,i) => (
              <div key={i} style={{ display:"flex", justifyContent:"space-between", padding:"9px 12px", borderRadius:8, marginBottom:4, background:"rgba(255,255,255,0.02)", border:"1px solid rgba(255,255,255,0.04)" }}>
                <div><span style={{ fontSize:13, fontWeight:600 }}>{u.teamName}</span><span style={{ fontSize:12, color:"rgba(255,255,255,0.35)", marginLeft:12 }}>S{(u.season||0)+1} · {u.type==="driver"?"Driver":u.type==="constructor"?"Constructor":"Track"} +1 {u.type==="track"?"Power-Up":"Rating"}</span></div>
                <div style={{ fontFamily:"Orbitron", fontSize:12, color:"#f4d03f", fontWeight:700 }}>−{u.cost}M</div>
              </div>
            ))}
          </div>
        )}
        <div style={{ textAlign:"center", marginTop:40, display:"flex", gap:16, justifyContent:"center", flexWrap:"wrap" }}>
          <button className="btn-secondary" onClick={onRestart} style={{ fontSize:15, padding:"14px 40px", letterSpacing:2 }}>↩ New Career</button>
          <button onClick={onRestartCareer} style={{ background:"linear-gradient(135deg,rgba(225,6,0,0.2),rgba(180,4,0,0.15))", border:"1px solid rgba(225,6,0,0.45)", borderRadius:10, padding:"14px 40px", color:"#e10600", fontFamily:"'Rajdhani',sans-serif", fontSize:15, fontWeight:700, letterSpacing:2, textTransform:"uppercase", cursor:"pointer", transition:"all 0.2s", boxShadow:"0 4px 16px rgba(225,6,0,0.15)" }}
            onMouseEnter={e=>e.currentTarget.style.background="linear-gradient(135deg,rgba(225,6,0,0.32),rgba(180,4,0,0.25))"}
            onMouseLeave={e=>e.currentTarget.style.background="linear-gradient(135deg,rgba(225,6,0,0.2),rgba(180,4,0,0.15))"}>
            🔁 Restart Career
          </button>
          <button onClick={onHallOfFame} style={{ background:"linear-gradient(135deg,rgba(244,208,63,0.15),rgba(212,172,13,0.1))", border:"1px solid rgba(244,208,63,0.35)", borderRadius:10, padding:"14px 32px", color:"#f4d03f", fontFamily:"'Rajdhani',sans-serif", fontSize:15, fontWeight:700, letterSpacing:2, textTransform:"uppercase", cursor:"pointer", transition:"all 0.2s" }}>
            🏆 Hall of Fame
          </button>
          <button onClick={onTrophyRoom} style={{ background:"linear-gradient(135deg,rgba(244,208,63,0.10),rgba(212,172,13,0.07))", border:"1px solid rgba(244,208,63,0.25)", borderRadius:10, padding:"14px 32px", color:"#f4d03f", fontFamily:"'Rajdhani',sans-serif", fontSize:15, fontWeight:700, letterSpacing:2, textTransform:"uppercase", cursor:"pointer", transition:"all 0.2s" }}>
            🎖 Trophy Room
          </button>
        </div>
      </div>
    </div>
  );
}


